-- -----------------------------------------------------------------------------
-- 17. REVIEWS (10 Reviews)
-- -----------------------------------------------------------------------------
INSERT INTO "Reviews" (
    "Id", "EnrollmentId", "Rating", "Comment",
    "TutorReply", "TutorRepliedAt",
    "IsRemoved", "RemovalReason", "RemovedAt", "RemovedByAdminId", "CreatedAt"
)
VALUES
    ('ffffffff-0001-0000-0000-000000000001', 'e1e1e1e1-0001-0000-0000-000000000002', 5, 'Khóa học vượt ngoài mong đợi của mình! Nhờ cô chữa bài Writing Task 2 rất kỹ từng lỗi ngữ pháp và cách dùng collocation tự nhiên mà em đã bứt phá từ 5.5 lên 7.0 Writing.', 'Cô rất tự hào về kết quả 7.0+ Writing của em Anh. Chúc em hoàn thành xuất sắc hồ sơ du học nhé!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days'),
    ('ffffffff-0001-0000-0000-000000000002', 'e1e1e1e1-0001-0000-0000-000000000010', 5, 'Cô đã truyền cho em niềm cảm hứng bất tận với môn Văn. Cách cô hướng dẫn đặt vấn đề mở bài và liên hệ lý luận văn học giúp bài viết của em sâu sắc hơn hẳn. Kì thi thử vừa rồi em đạt 9.0 Văn!', 'Cô rất xúc động khi đọc những dòng này của em Khoa. Ngòi bút của em ngày càng có chiều sâu và cảm xúc chân thành, hãy tự tin đạt 9+ nhé!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days'),
    ('ffffffff-0001-0000-0000-000000000003', 'e1e1e1e1-0001-0000-0000-000000000001', 5, 'Kiến thức bài bản, giáo án phân loại từ mức 7 điểm lên 9+ rất rõ ràng. Nhờ thầy chỉ các bẫy đề thi về hàm hợp và tiệm cận mà em không còn bị mất điểm oan.', 'Chúc mừng em đã vượt qua nỗi sợ môn Toán. Sự kiên trì và chăm chỉ của em xứng đáng với kết quả tuyệt vời này!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days'),
    ('ffffffff-0001-0000-0000-000000000004', 'e1e1e1e1-0001-0000-0000-000000000003', 4, 'Phương pháp vòng tròn lượng giác của thầy giải dao động cơ và mạch điện RLC xoay chiều quá đỉnh! Không cần nhớ máy móc công thức mà vẫn làm trắc nghiệm dưới 45 giây.', 'Thầy rất mừng vì em đã làm chủ được kỹ năng vòng tròn lượng giác. Cố gắng giữ vững phong độ này trong kỳ thi chính thức nhé!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days'),
    ('ffffffff-0001-0000-0000-000000000005', 'e1e1e1e1-0001-0000-0000-000000000004', 5, 'Khóa học luyện đề JLPT của Sensei bám sát cấu trúc đề thi thật. Em vừa nhận kết quả đỗ JLPT N3 với điểm phần Đọc hiểu gần như tuyệt đối!', 'Sensei chúc mừng em đỗ JLPT N3 điểm cao! Lên kế hoạch chinh phục tiếp mục tiêu N2 thôi nào!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days'),
    ('ffffffff-0001-0000-0000-000000000006', 'e1e1e1e1-0001-0000-0000-000000000005', 5, 'Cô đã truyền cho em niềm cảm hứng bất tận với môn Văn. Cách cô hướng dẫn đặt vấn đề mở bài và liên hệ lý luận văn học giúp bài viết của em sâu sắc hơn hẳn. Kì thi thử vừa rồi em đạt 9.0 Văn!', 'Cô rất xúc động khi đọc những dòng này của em Khoa. Ngòi bút của em ngày càng có chiều sâu và cảm xúc chân thành, hãy tự tin đạt 9+ nhé!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days'),
    ('ffffffff-0001-0000-0000-000000000007', 'e1e1e1e1-0001-0000-0000-000000000006', 5, 'Thầy dạy lập trình chuẩn doanh nghiệp! Hướng dẫn chi tiết từ Clean Architecture, CQRS, MediatR đến Entity Framework Core và tối ưu SQL. Em đã tự tay build được dự án backend hoàn chỉnh để đưa vào CV xin việc.', 'Chúc mừng em Đức đã hoàn thành dự án backend rất chỉn chu. Clean Architecture sẽ là lợi thế cạnh tranh lớn của em khi đi làm!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days'),
    ('ffffffff-0001-0000-0000-000000000008', 'e1e1e1e1-0001-0000-0000-000000000007', 4, 'Khóa học vượt ngoài mong đợi của mình! Nhờ cô chữa bài Writing Task 2 rất kỹ từng lỗi ngữ pháp và cách dùng collocation tự nhiên mà em đã bứt phá từ 5.5 lên 7.0 Writing.', 'Cô rất tự hào về kết quả 7.0+ Writing của em Hùng. Chúc em hoàn thành xuất sắc hồ sơ du học nhé!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days'),
    ('ffffffff-0001-0000-0000-000000000009', 'e1e1e1e1-0001-0000-0000-000000000008', 5, 'Kiến thức bài bản, giáo án phân loại từ mức 7 điểm lên 9+ rất rõ ràng. Nhờ thầy chỉ các bẫy đề thi về hàm hợp và tiệm cận mà em không còn bị mất điểm oan.', 'Chúc mừng em đã vượt qua nỗi sợ môn Toán. Sự kiên trì và chăm chỉ của em xứng đáng với kết quả tuyệt vời này!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days'),
    ('ffffffff-0001-0000-0000-000000000010', 'e1e1e1e1-0001-0000-0000-000000000009', 5, 'Gia đình rất cảm ơn thầy. Nhờ thầy kèm cặp kiên nhẫn mà con tôi từ chỗ sợ môn Toán nay đã hào hứng tự giác làm bài tập và điểm số tiến bộ vượt bậc!', 'Dạ thầy cảm ơn gia đình đã tin tưởng gửi gắm cháu. Bé tiếp thu rất nhanh và rất có tố chất tư duy logic ạ!', NOW() - INTERVAL '15 days', false, NULL, NULL, NULL, NOW() - INTERVAL '16 days');

