-- 8. AVAILABILITY SLOTS
INSERT INTO "AvailabilitySlots" ("Id", "TutorProfileId", "DayOfWeek", "StartTime", "EndTime", "IsActive")
SELECT ('b0a10000-0000-0000-0000-' || lpad(i::text, 12, '0'))::uuid, ('b2000000-0000-0000-0000-' || lpad(i::text, 12, '0'))::uuid, 'Monday', '18:00:00'::time, '21:00:00'::time, true FROM generate_series(1, 50) AS i ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "AvailabilitySlots" ("Id", "TutorProfileId", "DayOfWeek", "StartTime", "EndTime", "IsActive")
SELECT ('b0a20000-0000-0000-0000-' || lpad(i::text, 12, '0'))::uuid, ('b2000000-0000-0000-0000-' || lpad(i::text, 12, '0'))::uuid, 'Wednesday', '18:00:00'::time, '21:00:00'::time, true FROM generate_series(1, 50) AS i ON CONFLICT ("Id") DO NOTHING;
INSERT INTO "AvailabilitySlots" ("Id", "TutorProfileId", "DayOfWeek", "StartTime", "EndTime", "IsActive")
SELECT ('b0a30000-0000-0000-0000-' || lpad(i::text, 12, '0'))::uuid, ('b2000000-0000-0000-0000-' || lpad(i::text, 12, '0'))::uuid, 'Saturday', '08:30:00'::time, '11:30:00'::time, true FROM generate_series(1, 50) AS i ON CONFLICT ("Id") DO NOTHING;

-- 9. SERVICES (150 Services: 3 per tutor, tailored to their actual subject expertise)
INSERT INTO "Services" (
    "Id", "TutorProfileId", "SubjectId", "Title", "Description", 
    "LearningScope", "ExpectedOutcome", "TotalSessions", "SessionDurationMinutes", 
    "Price", "TeachingMode", "Status", "CreatedAt",
    "CoverImageUrl", "CurriculumJson", "TargetAudienceJson", "PrerequisitesJson", "FaqsJson"
) VALUES
    ('b7000000-0000-0000-0000-000000000001', 'b2000000-0000-0000-0000-000000000001', 'aaaaaaaa-0001-0000-0000-000000000001', 'Bứt Phá Điểm 9+ Môn Toán Thi Tốt Nghiệp THPT', 'Chương trình đào tạo chuyên sâu cá nhân hóa 1 kèm 1 theo năng lực thực tế của học viên.', 'Toàn bộ kiến thức lý thuyết nền tảng và bộ bài tập thực hành vận dụng cao bám sát thực tế.', 'Nắm chắc kiến thức bản chất, tự tin làm bài thi đạt kết quả xuất sắc vượt mục tiêu.', 12, 90, 3600000.00, 'Both', 'Published', NOW() - INTERVAL '66 days', 'https://images.unsplash.com/photo-1596495578065-6e0763fa1178?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Hàm số & Cực trị hàm đa thức bậc 3, bậc 4","description":"Xử lý thành thạo các câu hỏi trắc nghiệm mức 7.0 - 8.5 về đơn điệu và cực trị trong 90 giây/câu. Bài tập thực hành sau buổi học: Giải 30 bài tập trắc nghiệm hàm số trích từ đề thi thử Chuyên Khoa học Tự nhiên.","keyTopics":["Tính đơn điệu và điều kiện tham số m","Cực trị hàm bậc ba và đường thẳng qua hai cực trị","Kỹ thuật đạo hàm hàm hợp và hàm ẩn"],"durationMinutes":90},{"sessionIndex":2,"title":"Tiệm cận đồ thị hàm số & Đồ thị đạo hàm","description":"Nắm vững phương pháp suy đồ thị và giải quyết nhanh các bài toán cực trị hàm hợp mức 8.5+. Bài tập thực hành sau buổi học: Hoàn thành 25 bài tập sơ đồ V ghép trục cực trị hàm hợp.","keyTopics":["Tiệm cận đứng, tiệm cận ngang của hàm phân thức chứa căn","Phân tích đồ thị hàm f''(x) để tìm cực trị của hàm g(x) = f(u(x))","Kỹ thuật đếm số điểm cực trị bằng sơ đồ V"],"durationMinutes":90},{"sessionIndex":3,"title":"Tương giao đồ thị & Biện luận số nghiệm phương trình chứa tham số","description":"Tự tin giải quyết câu tương giao hàm số trong vòng 2 phút với độ chính xác tuyệt đối. Bài tập thực hành sau buổi học: Làm đề kiểm tra chuyên đề hàm số 30 câu trong 45 phút.","keyTopics":["Kỹ thuật cô lập tham số m","Phương pháp ghép trục giải quyết tương giao hàm hợp","Điểm uốn và tâm đối xứng của đồ thị"],"durationMinutes":90},{"sessionIndex":4,"title":"Mũ & Logarit: Phương trình, bất phương trình và bài toán Min-Max","description":"Nhận diện ngay dạng hàm đặc trưng và xử lý bất phương trình logarit phức tạp. Bài tập thực hành sau buổi học: Giải 20 câu hỏi VDC mũ - logarit trích từ đề chính thức các năm gần đây.","keyTopics":["Đặt ẩn phụ và phương pháp hàm đặc trưng","Bất phương trình logarit chứa tham số","Bài toán cực trị mũ - logarit vận dụng cao (VDC 9+)"],"durationMinutes":90},{"sessionIndex":5,"title":"Nguyên hàm & Tích phân: Kỹ thuật đổi biến và tích phân từng phần","description":"Nắm chắc 100% các câu hỏi tích phân cơ bản và nâng cao. Bài tập thực hành sau buổi học: Thực hành 35 câu bài tập tích phân hàm ẩn mức 8+.","keyTopics":["Công thức nguyên hàm nâng cao và vi phân nhanh","Đổi biến số lượng giác và hàm hữu tỉ","Tích phân từng phần dạng đặc biệt (hàm ẩn, f(x) kết hợp f''(x))"],"durationMinutes":90},{"sessionIndex":6,"title":"Ứng dụng hình học của tích phân: Diện tích hình phẳng & Thể tích tròn xoay","description":"Xử lý mượt mà bài toán ứng dụng tích phân thực tế hay xuất hiện trong cấu trúc mới. Bài tập thực hành sau buổi học: Giải 15 bài toán ứng dụng tích phân trong bài toán kinh tế và kiến trúc xây dựng.","keyTopics":["Công thức tính diện tích hình phẳng giới hạn bởi nhiều đồ thị","Thể tích vật thể tròn xoay quanh trục Ox, Oy","Bài toán thực tế tối ưu hóa chi phí sản xuất bằng tích phân"],"durationMinutes":90},{"sessionIndex":7,"title":"Hình học không gian: Khoảng cách và góc trong không gian cổ điển","description":"Giải bài toán khoảng cách không gian cổ điển trong 90 giây mà không bị rối hình. Bài tập thực hành sau buổi học: Làm phiếu 20 bài toán khoảng cách và góc đa diện khối chóp, lăng trụ.","keyTopics":["Phương pháp chân đường cao và kẻ phụ kẻ vuông góc","Khoảng cách từ điểm đến mặt phẳng, khoảng cách giữa 2 đường chéo nhau","Góc giữa đường thẳng và mặt phẳng, góc giữa hai mặt phẳng"],"durationMinutes":90},{"sessionIndex":8,"title":"Phương pháp tọa độ hóa (gắn hệ trục Oxyz) giải hình không gian","description":"Có vũ khí thứ hai cực mạnh để xử lý mọi bài hình không gian phức tạp khi bí dựng hình. Bài tập thực hành sau buổi học: Tọa độ hóa 10 bài toán khoảng cách từng xuất hiện trong đề thi THPT Quốc gia.","keyTopics":["Quy tắc chọn gốc tọa độ O và các trục Ox, Oy, Oz chuẩn","Chuyển đổi bài toán góc và khoảng cách sang công thức tọa độ","Ứng dụng Oxyz cho lăng trụ xiên và hình chóp có đáy bất kỳ"],"durationMinutes":90},{"sessionIndex":9,"title":"Mặt phẳng, đường thẳng và mặt cầu trong không gian Oxyz","description":"Làm chủ các dạng toán cơ bản và trung bình trong chuyên đề Oxyz để không mất điểm oan. Bài tập thực hành sau buổi học: Giải 30 câu trắc nghiệm Oxyz mức nhận biết - thông hiểu trong 30 phút.","keyTopics":["Vị trí tương đối và bài toán tương giao","Hình chiếu vuông góc của điểm lên mặt phẳng, đường thẳng","Phương trình mặt cầu ngoại tiếp tứ diện và tiếp xúc mặt phẳng"],"durationMinutes":90},{"sessionIndex":10,"title":"Cực trị không gian Oxyz & Kỹ thuật tâm tỉ cự, chuyển điểm","description":"Bẻ khóa câu hỏi phân loại Oxyz 9+ trong đề thi tốt nghiệp. Bài tập thực hành sau buổi học: Hoàn thành 15 bài tập VDC cực trị hình học Oxyz.","keyTopics":["Bài toán Min - Max biểu thức độ dài vectơ","Kỹ thuật tâm tỉ cự tìm điểm cố định I","Mặt phẳng thay đổi chứa đường thẳng tiếp xúc mặt cầu"],"durationMinutes":90},{"sessionIndex":11,"title":"Số phức & Các bài toán hình học số phức (Min - Max Modun)","description":"Ăn trọn điểm số phần số phức trong bài thi THPT. Bài tập thực hành sau buổi học: Làm phiếu 25 bài tập cực trị số phức vận dụng cao.","keyTopics":["Đại số số phức: Modun, liên hợp, nghiệm phức phương trình bậc 2","Tập hợp điểm biểu diễn số phức: Đường thẳng, đường tròn, elip","Cực trị số phức bằng phương pháp hình học và bất đẳng thức tam giác"],"durationMinutes":90},{"sessionIndex":12,"title":"Chiến thuật phòng thi, phân bổ thời gian & Thi thử chuẩn cấu trúc 2026","description":"Rèn luyện tâm lý vững vàng, kỹ năng bấm giờ và hoàn thành bài thi đạt điểm 9+. Bài tập thực hành sau buổi học: Chữa chi tiết từng câu sai trong đề thi thử và lập sổ tay lỗi sai cá nhân.","keyTopics":["Chiến thuật 35 câu đầu trong 35 phút (100% chính xác)","Kỹ thuật loại trừ đáp án, bấm máy tính Casio rà nghiệm","Làm bài thi thử 50 câu bấm giờ thật, phân tích lỗi sai và tổng kết"],"durationMinutes":90}]'::jsonb, '["Học sinh lớp 12 đang ở mức điểm 7.0 - 7.5 muốn bứt phá lên 8.8 - 9.6 điểm","Học sinh thi khối A00, A01, B00, D01 đặt nguyện vọng vào ĐH Y Dược, Ngoại Thương, Bách Khoa","Học sinh hay bị sai sót câu dễ và bế tắc trước các câu Vận dụng cao (VDC)"]'::jsonb, '["Đã nắm chắc lý thuyết sách giáo khoa Toán 12 chương trình chuẩn/nâng cao","Có máy tính Casio fx-580VNX hoặc fx-880BTG và tài liệu ôn thi chuyên đề"]'::jsonb, '[{"question":"Gia sư có chữa bài tập đề thi thử của các trường chuyên không?","answer":"Có. Toàn bộ bài tập vận dụng cao được tuyển chọn từ đề thi thử mới nhất năm 2025-2026 của Chuyên Sư Phạm, Chuyên KHTN, Chuyên Lam Sơn."},{"question":"Em hay tính ẩu sai câu dễ thì khóa học có cải thiện được không?","answer":"Gia sư rèn luyện bảng bẫy lỗi sai (Trap-list) riêng và kỹ thuật bấm máy kiểm tra ngược kết quả trong 15 giây."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000002', 'b2000000-0000-0000-0000-000000000001', 'aaaaaaaa-0001-0000-0000-000000000001', 'Chinh Phục Hình Học Không Gian & Oxyz Lớp 12', 'Khóa học bồi dưỡng chuyên đề cốt lõi giúp học viên lấp đầy lỗ hổng kiến thức và rèn phản xạ nhanh.', 'Các chuyên đề phân loại cao và chiến thuật xử lý các tình huống phức tạp trong bài thi/công việc.', 'Thành thạo kỹ năng giải quyết vấn đề, nâng cao rõ rệt tốc độ và độ chính xác.', 10, 90, 3000000.00, 'Both', 'Published', NOW() - INTERVAL '67 days', 'https://images.unsplash.com/photo-1509228468518-180dd4864904?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Góc trong không gian: Góc giữa đường thẳng và mặt phẳng, góc nhị diện","description":"Xác định chuẩn xác 100% các góc hình học không gian trong 60 giây. Bài tập thực hành sau buổi học: Giải 20 bài toán góc trong khối chóp và lăng trụ.","keyTopics":["Kỹ năng xác định hình chiếu vuông góc","Góc giữa hai đường thẳng chéo nhau","Góc giữa hai mặt phẳng bằng giao tuyến hoặc góc phẳng"],"durationMinutes":90},{"sessionIndex":2,"title":"Khoảng cách trong không gian cổ điển: Kỹ thuật dời điểm về chân đường cao","description":"Không còn lúng túng trước câu hỏi khoảng cách trong đề thi. Bài tập thực hành sau buổi học: Làm 15 bài toán khoảng cách từ các đề thi chuyên chọn lọc.","keyTopics":["Khoảng cách từ điểm bất kỳ đến mặt phẳng","Tỉ số khoảng cách và phương pháp song song / cắt nhau","Khoảng cách giữa hai đường thẳng chéo nhau"],"durationMinutes":90},{"sessionIndex":3,"title":"Thể tích khối đa diện: Khối chóp, lăng trụ & Tỉ số thể tích Simpson","description":"Tính toán nhanh thể tích các khối đa diện phức tạp bằng tỉ số thể tích. Bài tập thực hành sau buổi học: Hoàn thành phiếu bài tập 25 câu thể tích khối đa diện.","keyTopics":["Công thức thể tích V = 1/3 Bh và V = Bh","Định lý tỉ số thể tích Simpson cho khối chóp tam giác và mở rộng khối chóp tứ giác","Bài toán phân chia khối đa diện"],"durationMinutes":90},{"sessionIndex":4,"title":"Mặt nón, mặt trụ & Mặt cầu ngoại tiếp khối chóp","description":"Vẽ nhanh trục đường tròn đáy và mặt phẳng trung trực tìm bán kính mặt cầu R. Bài tập thực hành sau buổi học: Giải 20 bài toán mặt cầu ngoại tiếp hình chóp.","keyTopics":["Các yếu tố bán kính đáy r, đường sinh l, chiều cao h của nón và trụ","Công thức diện tích xung quanh, toàn phần và thể tích","Phương pháp xác định tâm và bán kính mặt cầu ngoại tiếp khối chóp có cạnh bên vuông góc đáy / mặt bên vuông góc đáy"],"durationMinutes":90},{"sessionIndex":5,"title":"Hệ trục tọa độ Oxyz: Tọa độ điểm, vectơ & Tích có hướng","description":"Thành thạo bấm máy Casio tích có hướng vectơ và gắn trục tọa độ chuẩn. Bài tập thực hành sau buổi học: Thực hành gắn trục Oxyz cho 8 dạng khối chóp thường gặp.","keyTopics":["Các phép toán vectơ trong không gian","Công thức tích có hướng và ứng dụng chứng minh đồng phẳng, tính diện tích tam giác","Phương pháp gắn hệ trục Oxyz vào hình không gian cổ điển"],"durationMinutes":90},{"sessionIndex":6,"title":"Phương trình mặt phẳng & Đường thẳng trong Oxyz","description":"Viết phương trình mặt phẳng và đường thẳng chính xác trong 45 giây. Bài tập thực hành sau buổi học: Làm 30 câu trắc nghiệm viết phương trình Oxyz cơ bản.","keyTopics":["Vectơ pháp tuyến, vectơ chỉ phương","Phương trình tổng quát mặt phẳng, phương trình chính tắc và tham số đường thẳng","Chuyển đổi linh hoạt giữa các dạng phương trình"],"durationMinutes":90},{"sessionIndex":7,"title":"Góc, khoảng cách & Vị trí tương đối trong Oxyz","description":"Áp dụng công thức giải quyết dứt điểm các bài toán không gian bằng đại số. Bài tập thực hành sau buổi học: Làm phiếu 20 bài toán tính toán khoảng cách bằng Oxyz.","keyTopics":["Công thức khoảng cách từ điểm đến mặt phẳng, khoảng cách giữa hai đường thẳng","Góc giữa hai đường thẳng, hai mặt phẳng, đường thẳng và mặt phẳng","Vị trí tương đối của hai đường thẳng: Cắt nhau, song song, chéo nhau"],"durationMinutes":90},{"sessionIndex":8,"title":"Mặt cầu trong Oxyz & Bài toán tương giao mặt phẳng - mặt cầu","description":"Xử lý thành thạo các bài toán mặt cầu cắt mặt phẳng. Bài tập thực hành sau buổi học: Giải 15 bài toán tương giao mặt phẳng và mặt cầu.","keyTopics":["Phương trình chính tắc và phương trình tổng quát mặt cầu","Điều kiện để mặt phẳng tiếp xúc mặt cầu hoặc cắt mặt cầu theo giao tuyến đường tròn","Đường tròn giao tuyến và bài toán tìm tâm, bán kính r"],"durationMinutes":90},{"sessionIndex":9,"title":"Kỹ thuật tâm tỉ cự và Cực trị Min-Max trong Oxyz","description":"Làm chủ dạng toán cực trị Oxyz 8.5+ hay xuất hiện ở cuối đề thi. Bài tập thực hành sau buổi học: Hoàn thành 12 bài toán cực trị tâm tỉ cự VDC.","keyTopics":["Tìm điểm cố định I thỏa mãn hệ thức vectơ","Bài toán tìm điểm M trên mặt phẳng sao cho tổng bình phương khoảng cách nhỏ nhất","Hình chiếu và điểm đối xứng"],"durationMinutes":90},{"sessionIndex":10,"title":"Tổng kết chuyên đề & Luyện giải đề thực chiến 100% câu hỏi Hình học","description":"Tự tin đạt điểm tối đa toàn bộ phần Hình học trong kỳ thi THPT. Bài tập thực hành sau buổi học: Chữa đề và hoàn thiện sổ tay công thức Hình học 12 cá nhân.","keyTopics":["Rà soát toàn bộ công thức và bảng tổng hợp mẹo làm nhanh","Giải trọn vẹn 2 đề thi chuyên sâu 25 câu Hình học không gian & Oxyz bấm giờ","Phân tích chiến thuật chọn phương pháp Cổ điển vs Oxyz"],"durationMinutes":90}]'::jsonb, '["Học sinh lớp 12 bị mất gốc hình học không gian lớp 11 hoặc sợ hình học Oxyz","Học sinh muốn học kỹ thuật tọa độ hóa để không phụ thuộc vào tư duy dựng hình cổ điển","Sĩ tử cần kiếm trọn 2.0 - 2.6 điểm phần Hình học trong đề thi tốt nghiệp THPT"]'::jsonb, '["Có kiến thức vectơ cơ bản của lớp 10 và quan hệ vuông góc lớp 11","Thước kẻ, compa, máy tính Casio fx-580VNX"]'::jsonb, '[{"question":"Em không biết vẽ hình phụ thì có học được phương pháp tọa độ hóa không?","answer":"Phương pháp tọa độ hóa Oxyz sinh ra chính là để giải cứu các bạn yếu vẽ hình phụ. Bạn chỉ cần chọn trục tọa độ là máy tính sẽ xử lý tính toán số học."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000003', 'b2000000-0000-0000-0000-000000000001', 'aaaaaaaa-0001-0000-0000-000000000002', 'Toán Tư Duy & Rèn Kỹ Năng Giải Bài Toán Thực Tế', 'Khóa đào tạo chuyên sâu ứng dụng thực tế giúp học viên đạt mục tiêu mong muốn trong thời gian ngắn nhất.', 'Hệ thống bài tập thực hành theo dự án mẫu và đề thi chuẩn quốc tế/quốc gia.', 'Làm chủ 100% kỹ năng, sẵn sàng chinh phục các kỳ thi và phỏng vấn thực tế.', 8, 90, 2500000.00, 'Both', 'Published', NOW() - INTERVAL '68 days', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Toán học tài chính: Lãi suất ngân hàng, gửi tiết kiệm & Trả góp","description":"Hiểu bản chất dòng tiền và tính toán chính xác lãi suất tiết kiệm. Bài tập thực hành sau buổi học: Giải 15 bài toán tài chính thực tế.","keyTopics":["Công thức lãi đơn và lãi kép","Bài toán gửi tiết kiệm ngân hàng có kỳ hạn","Kế hoạch mua hàng trả góp và chi phí tài chính"],"durationMinutes":90},{"sessionIndex":2,"title":"Tối ưu hóa kinh doanh: Lợi nhuận, Doanh thu & Chi phí sản xuất","description":"Vận dụng hàm số bậc hai giải bài toán kinh tế đời sống. Bài tập thực hành sau buổi học: Làm 12 bài toán tối ưu hóa doanh nghiệp.","keyTopics":["Mối quan hệ giữa giá bán, số lượng sản phẩm tiêu thụ và doanh thu","Xây dựng hàm số bậc hai biểu thị lợi nhuận theo giá bán","Tìm giá bán tối ưu để đạt lợi nhuận cực đại bằng đỉnh parabol"],"durationMinutes":90},{"sessionIndex":3,"title":"Hình học đo đạc thực tế: Đo chiều cao tòa nhà và khoảng cách không tới được","description":"Hiểu cách các kỹ sư trắc địa ứng dụng lượng giác vào thực tế. Bài tập thực hành sau buổi học: Giải 15 bài toán đo đạc thực địa.","keyTopics":["Sử dụng giác kế và thước đo góc","Ứng dụng tỉ số lượng giác sin, cos, tan đo chiều cao cây, ngọn hải đăng","Khoảng cách giữa hai điểm bị ngăn cách bởi dòng sông hoặc chướng ngại vật"],"durationMinutes":90},{"sessionIndex":4,"title":"Toán học kiến trúc: Diện tích sơn nhà, ốp lát gạch và lợp mái tôn","description":"Biết cách bóc tách khối lượng vật liệu xây dựng cho một căn phòng thực tế. Bài tập thực hành sau buổi học: Lập dự toán chi phí sơn sửa một căn phòng ngủ theo bản vẽ mẫu.","keyTopics":["Tính diện tích các mặt tường, trừ diện tích cửa sổ, cửa chính","Tính toán số lượng gạch cần lát sàn và tỉ lệ hao hụt","Diện tích mái ngói hình chóp cụt và khối lăng trụ"],"durationMinutes":90},{"sessionIndex":5,"title":"Toán học dinh dưỡng & Nồng độ dung dịch hóa chất thực tế","description":"Tính toán chuẩn nồng độ pha chế trong đời sống hàng ngày. Bài tập thực hành sau buổi học: Giải 15 bài toán pha trộn dung dịch và dinh dưỡng.","keyTopics":["Tỉ lệ phần trăm dinh dưỡng calo, protein, carb trong khẩu phần ăn","Bài toán pha trộn dung dịch: Muối, cồn sát khuẩn 70 độ, nước đường","Thiết lập phương trình cân bằng nồng độ phần trăm"],"durationMinutes":90},{"sessionIndex":6,"title":"Thống kê & Xác suất thực nghiệm trong phân tích dữ liệu đời sống","description":"Đọc hiểu biểu đồ báo cáo và phân tích số liệu khoa học. Bài tập thực hành sau buổi học: Phân tích bảng số liệu khảo sát người tiêu dùng và viết báo cáo ngắn.","keyTopics":["Thu thập dữ liệu, vẽ biểu đồ hình quạt tròn và biểu đồ đoạn thẳng","Số trung bình cộng, trung vị, mốt và ý nghĩa thực tế","Xác suất thực nghiệm trong trò chơi may rủi và dự báo thời tiết"],"durationMinutes":90},{"sessionIndex":7,"title":"Tư duy logic giải đố & Bài toán chiến thuật trò chơi (Game Theory)","description":"Rèn luyện tư duy logic sắc bén, tư duy thuật toán. Bài tập thực hành sau buổi học: Giải 10 câu đố logic kinh điển.","keyTopics":["Nguyên lý Dirichlet (nguyên lý chuồng bồ câu) ứng dụng","Phương pháp suy luận ngược từ kết quả","Chiến thuật giành chiến thắng trong trò chơi bốc sỏi (Nim game)"],"durationMinutes":90},{"sessionIndex":8,"title":"Báo cáo dự án thực tế & Tổng kết phương pháp tư duy mô hình hóa","description":"Có năng lực chuyển đổi các vấn đề thực tiễn phức tạp thành bài toán cụ thể. Bài tập thực hành sau buổi học: Hoàn thành bài tập dự án ứng dụng toán học cá nhân.","keyTopics":["Quy trình mô hình hóa toán học 4 bước: Đời thực -> Toán học -> Giải toán -> Ứng dụng","Thực hành giải trọn vẹn 1 đề thi chuyên đề Toán thực tế 90 phút","Đánh giá năng lực tư duy giải quyết vấn đề của học viên"],"durationMinutes":90}]'::jsonb, '["Học sinh THCS theo chương trình SGK mới (Cánh Diều, Kết Nối Tri Thức, Chân Trời Sáng Tạo)","Học sinh muốn rèn luyện tư duy phản biện, giải quyết các bài toán tài chính, đo đạc thực tế"]'::jsonb, '["Sổ tay ghi chép","Máy tính bỏ túi"]'::jsonb, '[{"question":"Chương trình mới có nhiều bài toán thực tế không?","answer":"Chương trình mới dành tới 25-30% đề thi cho các bài toán ứng dụng thực tế: Tài chính cá nhân, lãi suất ngân hàng, hình học không gian đời sống."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000004', 'b2000000-0000-0000-0000-000000000002', 'aaaaaaaa-0001-0000-0000-000000000001', 'Bứt Phá Điểm 9+ Môn Toán Thi Tốt Nghiệp THPT', 'Chương trình đào tạo chuyên sâu cá nhân hóa 1 kèm 1 theo năng lực thực tế của học viên.', 'Toàn bộ kiến thức lý thuyết nền tảng và bộ bài tập thực hành vận dụng cao bám sát thực tế.', 'Nắm chắc kiến thức bản chất, tự tin làm bài thi đạt kết quả xuất sắc vượt mục tiêu.', 12, 90, 3600000.00, 'Online', 'Published', NOW() - INTERVAL '69 days', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Hàm số & Cực trị hàm đa thức bậc 3, bậc 4","description":"Xử lý thành thạo các câu hỏi trắc nghiệm mức 7.0 - 8.5 về đơn điệu và cực trị trong 90 giây/câu. Bài tập thực hành sau buổi học: Giải 30 bài tập trắc nghiệm hàm số trích từ đề thi thử Chuyên Khoa học Tự nhiên.","keyTopics":["Tính đơn điệu và điều kiện tham số m","Cực trị hàm bậc ba và đường thẳng qua hai cực trị","Kỹ thuật đạo hàm hàm hợp và hàm ẩn"],"durationMinutes":90},{"sessionIndex":2,"title":"Tiệm cận đồ thị hàm số & Đồ thị đạo hàm","description":"Nắm vững phương pháp suy đồ thị và giải quyết nhanh các bài toán cực trị hàm hợp mức 8.5+. Bài tập thực hành sau buổi học: Hoàn thành 25 bài tập sơ đồ V ghép trục cực trị hàm hợp.","keyTopics":["Tiệm cận đứng, tiệm cận ngang của hàm phân thức chứa căn","Phân tích đồ thị hàm f''(x) để tìm cực trị của hàm g(x) = f(u(x))","Kỹ thuật đếm số điểm cực trị bằng sơ đồ V"],"durationMinutes":90},{"sessionIndex":3,"title":"Tương giao đồ thị & Biện luận số nghiệm phương trình chứa tham số","description":"Tự tin giải quyết câu tương giao hàm số trong vòng 2 phút với độ chính xác tuyệt đối. Bài tập thực hành sau buổi học: Làm đề kiểm tra chuyên đề hàm số 30 câu trong 45 phút.","keyTopics":["Kỹ thuật cô lập tham số m","Phương pháp ghép trục giải quyết tương giao hàm hợp","Điểm uốn và tâm đối xứng của đồ thị"],"durationMinutes":90},{"sessionIndex":4,"title":"Mũ & Logarit: Phương trình, bất phương trình và bài toán Min-Max","description":"Nhận diện ngay dạng hàm đặc trưng và xử lý bất phương trình logarit phức tạp. Bài tập thực hành sau buổi học: Giải 20 câu hỏi VDC mũ - logarit trích từ đề chính thức các năm gần đây.","keyTopics":["Đặt ẩn phụ và phương pháp hàm đặc trưng","Bất phương trình logarit chứa tham số","Bài toán cực trị mũ - logarit vận dụng cao (VDC 9+)"],"durationMinutes":90},{"sessionIndex":5,"title":"Nguyên hàm & Tích phân: Kỹ thuật đổi biến và tích phân từng phần","description":"Nắm chắc 100% các câu hỏi tích phân cơ bản và nâng cao. Bài tập thực hành sau buổi học: Thực hành 35 câu bài tập tích phân hàm ẩn mức 8+.","keyTopics":["Công thức nguyên hàm nâng cao và vi phân nhanh","Đổi biến số lượng giác và hàm hữu tỉ","Tích phân từng phần dạng đặc biệt (hàm ẩn, f(x) kết hợp f''(x))"],"durationMinutes":90},{"sessionIndex":6,"title":"Ứng dụng hình học của tích phân: Diện tích hình phẳng & Thể tích tròn xoay","description":"Xử lý mượt mà bài toán ứng dụng tích phân thực tế hay xuất hiện trong cấu trúc mới. Bài tập thực hành sau buổi học: Giải 15 bài toán ứng dụng tích phân trong bài toán kinh tế và kiến trúc xây dựng.","keyTopics":["Công thức tính diện tích hình phẳng giới hạn bởi nhiều đồ thị","Thể tích vật thể tròn xoay quanh trục Ox, Oy","Bài toán thực tế tối ưu hóa chi phí sản xuất bằng tích phân"],"durationMinutes":90},{"sessionIndex":7,"title":"Hình học không gian: Khoảng cách và góc trong không gian cổ điển","description":"Giải bài toán khoảng cách không gian cổ điển trong 90 giây mà không bị rối hình. Bài tập thực hành sau buổi học: Làm phiếu 20 bài toán khoảng cách và góc đa diện khối chóp, lăng trụ.","keyTopics":["Phương pháp chân đường cao và kẻ phụ kẻ vuông góc","Khoảng cách từ điểm đến mặt phẳng, khoảng cách giữa 2 đường chéo nhau","Góc giữa đường thẳng và mặt phẳng, góc giữa hai mặt phẳng"],"durationMinutes":90},{"sessionIndex":8,"title":"Phương pháp tọa độ hóa (gắn hệ trục Oxyz) giải hình không gian","description":"Có vũ khí thứ hai cực mạnh để xử lý mọi bài hình không gian phức tạp khi bí dựng hình. Bài tập thực hành sau buổi học: Tọa độ hóa 10 bài toán khoảng cách từng xuất hiện trong đề thi THPT Quốc gia.","keyTopics":["Quy tắc chọn gốc tọa độ O và các trục Ox, Oy, Oz chuẩn","Chuyển đổi bài toán góc và khoảng cách sang công thức tọa độ","Ứng dụng Oxyz cho lăng trụ xiên và hình chóp có đáy bất kỳ"],"durationMinutes":90},{"sessionIndex":9,"title":"Mặt phẳng, đường thẳng và mặt cầu trong không gian Oxyz","description":"Làm chủ các dạng toán cơ bản và trung bình trong chuyên đề Oxyz để không mất điểm oan. Bài tập thực hành sau buổi học: Giải 30 câu trắc nghiệm Oxyz mức nhận biết - thông hiểu trong 30 phút.","keyTopics":["Vị trí tương đối và bài toán tương giao","Hình chiếu vuông góc của điểm lên mặt phẳng, đường thẳng","Phương trình mặt cầu ngoại tiếp tứ diện và tiếp xúc mặt phẳng"],"durationMinutes":90},{"sessionIndex":10,"title":"Cực trị không gian Oxyz & Kỹ thuật tâm tỉ cự, chuyển điểm","description":"Bẻ khóa câu hỏi phân loại Oxyz 9+ trong đề thi tốt nghiệp. Bài tập thực hành sau buổi học: Hoàn thành 15 bài tập VDC cực trị hình học Oxyz.","keyTopics":["Bài toán Min - Max biểu thức độ dài vectơ","Kỹ thuật tâm tỉ cự tìm điểm cố định I","Mặt phẳng thay đổi chứa đường thẳng tiếp xúc mặt cầu"],"durationMinutes":90},{"sessionIndex":11,"title":"Số phức & Các bài toán hình học số phức (Min - Max Modun)","description":"Ăn trọn điểm số phần số phức trong bài thi THPT. Bài tập thực hành sau buổi học: Làm phiếu 25 bài tập cực trị số phức vận dụng cao.","keyTopics":["Đại số số phức: Modun, liên hợp, nghiệm phức phương trình bậc 2","Tập hợp điểm biểu diễn số phức: Đường thẳng, đường tròn, elip","Cực trị số phức bằng phương pháp hình học và bất đẳng thức tam giác"],"durationMinutes":90},{"sessionIndex":12,"title":"Chiến thuật phòng thi, phân bổ thời gian & Thi thử chuẩn cấu trúc 2026","description":"Rèn luyện tâm lý vững vàng, kỹ năng bấm giờ và hoàn thành bài thi đạt điểm 9+. Bài tập thực hành sau buổi học: Chữa chi tiết từng câu sai trong đề thi thử và lập sổ tay lỗi sai cá nhân.","keyTopics":["Chiến thuật 35 câu đầu trong 35 phút (100% chính xác)","Kỹ thuật loại trừ đáp án, bấm máy tính Casio rà nghiệm","Làm bài thi thử 50 câu bấm giờ thật, phân tích lỗi sai và tổng kết"],"durationMinutes":90}]'::jsonb, '["Học sinh lớp 12 đang ở mức điểm 7.0 - 7.5 muốn bứt phá lên 8.8 - 9.6 điểm","Học sinh thi khối A00, A01, B00, D01 đặt nguyện vọng vào ĐH Y Dược, Ngoại Thương, Bách Khoa","Học sinh hay bị sai sót câu dễ và bế tắc trước các câu Vận dụng cao (VDC)"]'::jsonb, '["Đã nắm chắc lý thuyết sách giáo khoa Toán 12 chương trình chuẩn/nâng cao","Có máy tính Casio fx-580VNX hoặc fx-880BTG và tài liệu ôn thi chuyên đề"]'::jsonb, '[{"question":"Gia sư có chữa bài tập đề thi thử của các trường chuyên không?","answer":"Có. Toàn bộ bài tập vận dụng cao được tuyển chọn từ đề thi thử mới nhất năm 2025-2026 của Chuyên Sư Phạm, Chuyên KHTN, Chuyên Lam Sơn."},{"question":"Em hay tính ẩu sai câu dễ thì khóa học có cải thiện được không?","answer":"Gia sư rèn luyện bảng bẫy lỗi sai (Trap-list) riêng và kỹ thuật bấm máy kiểm tra ngược kết quả trong 15 giây."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000005', 'b2000000-0000-0000-0000-000000000002', 'aaaaaaaa-0001-0000-0000-000000000001', 'Chinh Phục Hình Học Không Gian & Oxyz Lớp 12', 'Khóa học bồi dưỡng chuyên đề cốt lõi giúp học viên lấp đầy lỗ hổng kiến thức và rèn phản xạ nhanh.', 'Các chuyên đề phân loại cao và chiến thuật xử lý các tình huống phức tạp trong bài thi/công việc.', 'Thành thạo kỹ năng giải quyết vấn đề, nâng cao rõ rệt tốc độ và độ chính xác.', 10, 90, 3000000.00, 'Online', 'Published', NOW() - INTERVAL '70 days', 'https://images.unsplash.com/photo-1596495578065-6e0763fa1178?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Góc trong không gian: Góc giữa đường thẳng và mặt phẳng, góc nhị diện","description":"Xác định chuẩn xác 100% các góc hình học không gian trong 60 giây. Bài tập thực hành sau buổi học: Giải 20 bài toán góc trong khối chóp và lăng trụ.","keyTopics":["Kỹ năng xác định hình chiếu vuông góc","Góc giữa hai đường thẳng chéo nhau","Góc giữa hai mặt phẳng bằng giao tuyến hoặc góc phẳng"],"durationMinutes":90},{"sessionIndex":2,"title":"Khoảng cách trong không gian cổ điển: Kỹ thuật dời điểm về chân đường cao","description":"Không còn lúng túng trước câu hỏi khoảng cách trong đề thi. Bài tập thực hành sau buổi học: Làm 15 bài toán khoảng cách từ các đề thi chuyên chọn lọc.","keyTopics":["Khoảng cách từ điểm bất kỳ đến mặt phẳng","Tỉ số khoảng cách và phương pháp song song / cắt nhau","Khoảng cách giữa hai đường thẳng chéo nhau"],"durationMinutes":90},{"sessionIndex":3,"title":"Thể tích khối đa diện: Khối chóp, lăng trụ & Tỉ số thể tích Simpson","description":"Tính toán nhanh thể tích các khối đa diện phức tạp bằng tỉ số thể tích. Bài tập thực hành sau buổi học: Hoàn thành phiếu bài tập 25 câu thể tích khối đa diện.","keyTopics":["Công thức thể tích V = 1/3 Bh và V = Bh","Định lý tỉ số thể tích Simpson cho khối chóp tam giác và mở rộng khối chóp tứ giác","Bài toán phân chia khối đa diện"],"durationMinutes":90},{"sessionIndex":4,"title":"Mặt nón, mặt trụ & Mặt cầu ngoại tiếp khối chóp","description":"Vẽ nhanh trục đường tròn đáy và mặt phẳng trung trực tìm bán kính mặt cầu R. Bài tập thực hành sau buổi học: Giải 20 bài toán mặt cầu ngoại tiếp hình chóp.","keyTopics":["Các yếu tố bán kính đáy r, đường sinh l, chiều cao h của nón và trụ","Công thức diện tích xung quanh, toàn phần và thể tích","Phương pháp xác định tâm và bán kính mặt cầu ngoại tiếp khối chóp có cạnh bên vuông góc đáy / mặt bên vuông góc đáy"],"durationMinutes":90},{"sessionIndex":5,"title":"Hệ trục tọa độ Oxyz: Tọa độ điểm, vectơ & Tích có hướng","description":"Thành thạo bấm máy Casio tích có hướng vectơ và gắn trục tọa độ chuẩn. Bài tập thực hành sau buổi học: Thực hành gắn trục Oxyz cho 8 dạng khối chóp thường gặp.","keyTopics":["Các phép toán vectơ trong không gian","Công thức tích có hướng và ứng dụng chứng minh đồng phẳng, tính diện tích tam giác","Phương pháp gắn hệ trục Oxyz vào hình không gian cổ điển"],"durationMinutes":90},{"sessionIndex":6,"title":"Phương trình mặt phẳng & Đường thẳng trong Oxyz","description":"Viết phương trình mặt phẳng và đường thẳng chính xác trong 45 giây. Bài tập thực hành sau buổi học: Làm 30 câu trắc nghiệm viết phương trình Oxyz cơ bản.","keyTopics":["Vectơ pháp tuyến, vectơ chỉ phương","Phương trình tổng quát mặt phẳng, phương trình chính tắc và tham số đường thẳng","Chuyển đổi linh hoạt giữa các dạng phương trình"],"durationMinutes":90},{"sessionIndex":7,"title":"Góc, khoảng cách & Vị trí tương đối trong Oxyz","description":"Áp dụng công thức giải quyết dứt điểm các bài toán không gian bằng đại số. Bài tập thực hành sau buổi học: Làm phiếu 20 bài toán tính toán khoảng cách bằng Oxyz.","keyTopics":["Công thức khoảng cách từ điểm đến mặt phẳng, khoảng cách giữa hai đường thẳng","Góc giữa hai đường thẳng, hai mặt phẳng, đường thẳng và mặt phẳng","Vị trí tương đối của hai đường thẳng: Cắt nhau, song song, chéo nhau"],"durationMinutes":90},{"sessionIndex":8,"title":"Mặt cầu trong Oxyz & Bài toán tương giao mặt phẳng - mặt cầu","description":"Xử lý thành thạo các bài toán mặt cầu cắt mặt phẳng. Bài tập thực hành sau buổi học: Giải 15 bài toán tương giao mặt phẳng và mặt cầu.","keyTopics":["Phương trình chính tắc và phương trình tổng quát mặt cầu","Điều kiện để mặt phẳng tiếp xúc mặt cầu hoặc cắt mặt cầu theo giao tuyến đường tròn","Đường tròn giao tuyến và bài toán tìm tâm, bán kính r"],"durationMinutes":90},{"sessionIndex":9,"title":"Kỹ thuật tâm tỉ cự và Cực trị Min-Max trong Oxyz","description":"Làm chủ dạng toán cực trị Oxyz 8.5+ hay xuất hiện ở cuối đề thi. Bài tập thực hành sau buổi học: Hoàn thành 12 bài toán cực trị tâm tỉ cự VDC.","keyTopics":["Tìm điểm cố định I thỏa mãn hệ thức vectơ","Bài toán tìm điểm M trên mặt phẳng sao cho tổng bình phương khoảng cách nhỏ nhất","Hình chiếu và điểm đối xứng"],"durationMinutes":90},{"sessionIndex":10,"title":"Tổng kết chuyên đề & Luyện giải đề thực chiến 100% câu hỏi Hình học","description":"Tự tin đạt điểm tối đa toàn bộ phần Hình học trong kỳ thi THPT. Bài tập thực hành sau buổi học: Chữa đề và hoàn thiện sổ tay công thức Hình học 12 cá nhân.","keyTopics":["Rà soát toàn bộ công thức và bảng tổng hợp mẹo làm nhanh","Giải trọn vẹn 2 đề thi chuyên sâu 25 câu Hình học không gian & Oxyz bấm giờ","Phân tích chiến thuật chọn phương pháp Cổ điển vs Oxyz"],"durationMinutes":90}]'::jsonb, '["Học sinh lớp 12 bị mất gốc hình học không gian lớp 11 hoặc sợ hình học Oxyz","Học sinh muốn học kỹ thuật tọa độ hóa để không phụ thuộc vào tư duy dựng hình cổ điển","Sĩ tử cần kiếm trọn 2.0 - 2.6 điểm phần Hình học trong đề thi tốt nghiệp THPT"]'::jsonb, '["Có kiến thức vectơ cơ bản của lớp 10 và quan hệ vuông góc lớp 11","Thước kẻ, compa, máy tính Casio fx-580VNX"]'::jsonb, '[{"question":"Em không biết vẽ hình phụ thì có học được phương pháp tọa độ hóa không?","answer":"Phương pháp tọa độ hóa Oxyz sinh ra chính là để giải cứu các bạn yếu vẽ hình phụ. Bạn chỉ cần chọn trục tọa độ là máy tính sẽ xử lý tính toán số học."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000006', 'b2000000-0000-0000-0000-000000000002', 'aaaaaaaa-0001-0000-0000-000000000012', 'Luyện Kỹ Năng Tư Duy Định Lượng & Xử Lý Số Liệu ĐGNL', 'Khóa đào tạo chuyên sâu ứng dụng thực tế giúp học viên đạt mục tiêu mong muốn trong thời gian ngắn nhất.', 'Hệ thống bài tập thực hành theo dự án mẫu và đề thi chuẩn quốc tế/quốc gia.', 'Làm chủ 100% kỹ năng, sẵn sàng chinh phục các kỳ thi và phỏng vấn thực tế.', 8, 90, 2500000.00, 'Online', 'Published', NOW() - INTERVAL '71 days', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Tổng quan cấu trúc 120 câu / 150 phút & Chiến thuật phân bổ thời gian","description":"Nắm chắc cấu trúc đề và tối ưu hóa tốc độ làm bài 75 giây/câu. Bài tập thực hành sau buổi học: Làm bài khảo sát năng lực đầu vào 60 câu.","keyTopics":["Chiến thuật làm bài 3 vòng: Vòng 1 ăn chắc 70 câu dễ trong 60 phút, Vòng 2 xử lý 35 câu suy luận trong 60 phút, Vòng 3 giải quyết 15 câu khó trong 30 phút","Quy tắc không bỏ trống bất kỳ câu trả lời nào (không trừ điểm câu sai)"],"durationMinutes":90},{"sessionIndex":2,"title":"Phần Tiếng Việt: Quy tắc chính tả, Nghĩa của từ & Ngữ pháp phong cách học","description":"Ăn trọn 20/20 câu hỏi phần Sử dụng ngôn ngữ Tiếng Việt. Bài tập thực hành sau buổi học: Giải 40 câu hỏi trắc nghiệm tiếng Việt đề thi các năm.","keyTopics":["Nhận biết lỗi sai dùng từ, lỗi logic trong câu văn","Phân tích phong cách ngôn ngữ chức năng và thao tác lập luận","Xử lý các đoạn văn trích từ tác phẩm văn học hiện đại"],"durationMinutes":90},{"sessionIndex":3,"title":"Phần Tiếng Anh: Ngữ pháp, Từ vựng & Kỹ năng Đọc hiểu văn bản APT","description":"Đạt tối thiểu 18/20 câu hỏi phần Tiếng Anh. Bài tập thực hành sau buổi học: Làm 40 câu hỏi trắc nghiệm tiếng Anh format ĐGNL.","keyTopics":["Xác định lỗi sai trong câu tiếng Anh (Error Identification)","Điền từ vào chỗ trống trong đoạn văn (Cloze test)","Kỹ thuật đọc lướt tìm ý chính và suy luận đoạn văn ngắn"],"durationMinutes":90},{"sessionIndex":4,"title":"Toán học ĐGNL: Đại số, Giải tích, Hình học & Xác suất thống kê","description":"Giải quyết 30 câu hỏi Toán học với độ chính xác cao. Bài tập thực hành sau buổi học: Giải 30 câu hỏi Toán học định lượng.","keyTopics":["Các bài toán tính nhanh mũ, logarit, tích phân không cần giải chi tiết","Tập hợp điểm và hình học tọa độ phẳng","Toán xác suất tổ hợp thực tế"],"durationMinutes":90},{"sessionIndex":5,"title":"Tư duy logic 1: Bài toán sắp xếp thứ tự & Ghép nối dữ kiện","description":"Bẻ khóa các bài toán logic 4-5 câu hỏi chùm trong 3 phút. Bài tập thực hành sau buổi học: Làm 6 bài tập chùm logic sắp xếp.","keyTopics":["Mô hình bài toán xếp hàng, chọn ghế, lịch công tác","Kỹ thuật kẻ bảng ma trận chân lý (Logic Grid) loại trừ khả năng","Suy luận điều kiện cần và đủ"],"durationMinutes":90},{"sessionIndex":6,"title":"Tư duy logic 2: Suy luận mệnh đề, Quan hệ huyết thống & Luật suy diễn","description":"Xử lý chính xác các câu hỏi logic trừu tượng không bị rối. Bài tập thực hành sau buổi học: Giải 20 câu hỏi suy luận mệnh đề.","keyTopics":["Mệnh đề kéo theo (P => Q), mệnh đề đảo và phản đảo","Phép suy luận tương đương và quy tắc tam đoạn luận","Bài toán gia phả, phân vai và quy tắc trò chơi"],"durationMinutes":90},{"sessionIndex":7,"title":"Xử lý số liệu: Đọc hiểu biểu đồ tròn, biểu đồ cột & Bảng số liệu thống kê","description":"Ăn trọn 100% điểm số phần Phân tích số liệu. Bài tập thực hành sau buổi học: Làm 5 bài chùm phân tích biểu đồ thống kê.","keyTopics":["Tính toán tỉ lệ tăng trưởng phần trăm, tốc độ tăng trưởng bình quân","So sánh tương quan giữa các nhóm đại lượng","Kỹ thuật ước lượng số học làm tròn nhanh mà không cần bấm máy tính chi tiết"],"durationMinutes":90},{"sessionIndex":8,"title":"Giải quyết vấn đề: Hóa học & Sinh học thực nghiệm trong đề thi APT","description":"Tự tin giải quyết các câu hỏi Khoa học tự nhiên. Bài tập thực hành sau buổi học: Làm 20 câu hỏi KHTN trích từ đề chính thức.","keyTopics":["Phân tích thí nghiệm Hóa học, hiện tượng phản ứng và bài toán thực tiễn","Đọc hiểu sơ đồ di truyền, chuỗi sinh thái và biểu đồ sinh học","Kỹ năng trích xuất thông tin từ đoạn văn khoa học"],"durationMinutes":90}]'::jsonb, '["Học sinh lớp 12 tham gia kỳ thi Đánh Giá Năng Lực ĐHQG TP.HCM (APT)","Học sinh muốn đạt trên 850 - 950 điểm để xét tuyển vào ĐH Bách Khoa, KHTN, Kinh Tế Luật"]'::jsonb, '["Đã nắm kiến thức cơ bản các môn THPT","Máy tính Casio fx-580"]'::jsonb, '[{"question":"Cấu trúc đề ĐGNL ĐHQG TP.HCM có giống đề thi tốt nghiệp không?","answer":"Hoàn toàn khác. Đề gồm 120 câu trắc nghiệm trong 150 phút, kiểm tra toàn diện 3 phần: Sử dụng ngôn ngữ (Tiếng Việt & Anh), Toán học & Tư duy logic, và Giải quyết vấn đề (Khoa học)."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000007', 'b2000000-0000-0000-0000-000000000003', 'aaaaaaaa-0001-0000-0000-000000000001', 'Bứt Phá Điểm 9+ Môn Toán Thi Tốt Nghiệp THPT', 'Chương trình đào tạo chuyên sâu cá nhân hóa 1 kèm 1 theo năng lực thực tế của học viên.', 'Toàn bộ kiến thức lý thuyết nền tảng và bộ bài tập thực hành vận dụng cao bám sát thực tế.', 'Nắm chắc kiến thức bản chất, tự tin làm bài thi đạt kết quả xuất sắc vượt mục tiêu.', 12, 90, 3600000.00, 'Both', 'Published', NOW() - INTERVAL '72 days', 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Hàm số & Cực trị hàm đa thức bậc 3, bậc 4","description":"Xử lý thành thạo các câu hỏi trắc nghiệm mức 7.0 - 8.5 về đơn điệu và cực trị trong 90 giây/câu. Bài tập thực hành sau buổi học: Giải 30 bài tập trắc nghiệm hàm số trích từ đề thi thử Chuyên Khoa học Tự nhiên.","keyTopics":["Tính đơn điệu và điều kiện tham số m","Cực trị hàm bậc ba và đường thẳng qua hai cực trị","Kỹ thuật đạo hàm hàm hợp và hàm ẩn"],"durationMinutes":90},{"sessionIndex":2,"title":"Tiệm cận đồ thị hàm số & Đồ thị đạo hàm","description":"Nắm vững phương pháp suy đồ thị và giải quyết nhanh các bài toán cực trị hàm hợp mức 8.5+. Bài tập thực hành sau buổi học: Hoàn thành 25 bài tập sơ đồ V ghép trục cực trị hàm hợp.","keyTopics":["Tiệm cận đứng, tiệm cận ngang của hàm phân thức chứa căn","Phân tích đồ thị hàm f''(x) để tìm cực trị của hàm g(x) = f(u(x))","Kỹ thuật đếm số điểm cực trị bằng sơ đồ V"],"durationMinutes":90},{"sessionIndex":3,"title":"Tương giao đồ thị & Biện luận số nghiệm phương trình chứa tham số","description":"Tự tin giải quyết câu tương giao hàm số trong vòng 2 phút với độ chính xác tuyệt đối. Bài tập thực hành sau buổi học: Làm đề kiểm tra chuyên đề hàm số 30 câu trong 45 phút.","keyTopics":["Kỹ thuật cô lập tham số m","Phương pháp ghép trục giải quyết tương giao hàm hợp","Điểm uốn và tâm đối xứng của đồ thị"],"durationMinutes":90},{"sessionIndex":4,"title":"Mũ & Logarit: Phương trình, bất phương trình và bài toán Min-Max","description":"Nhận diện ngay dạng hàm đặc trưng và xử lý bất phương trình logarit phức tạp. Bài tập thực hành sau buổi học: Giải 20 câu hỏi VDC mũ - logarit trích từ đề chính thức các năm gần đây.","keyTopics":["Đặt ẩn phụ và phương pháp hàm đặc trưng","Bất phương trình logarit chứa tham số","Bài toán cực trị mũ - logarit vận dụng cao (VDC 9+)"],"durationMinutes":90},{"sessionIndex":5,"title":"Nguyên hàm & Tích phân: Kỹ thuật đổi biến và tích phân từng phần","description":"Nắm chắc 100% các câu hỏi tích phân cơ bản và nâng cao. Bài tập thực hành sau buổi học: Thực hành 35 câu bài tập tích phân hàm ẩn mức 8+.","keyTopics":["Công thức nguyên hàm nâng cao và vi phân nhanh","Đổi biến số lượng giác và hàm hữu tỉ","Tích phân từng phần dạng đặc biệt (hàm ẩn, f(x) kết hợp f''(x))"],"durationMinutes":90},{"sessionIndex":6,"title":"Ứng dụng hình học của tích phân: Diện tích hình phẳng & Thể tích tròn xoay","description":"Xử lý mượt mà bài toán ứng dụng tích phân thực tế hay xuất hiện trong cấu trúc mới. Bài tập thực hành sau buổi học: Giải 15 bài toán ứng dụng tích phân trong bài toán kinh tế và kiến trúc xây dựng.","keyTopics":["Công thức tính diện tích hình phẳng giới hạn bởi nhiều đồ thị","Thể tích vật thể tròn xoay quanh trục Ox, Oy","Bài toán thực tế tối ưu hóa chi phí sản xuất bằng tích phân"],"durationMinutes":90},{"sessionIndex":7,"title":"Hình học không gian: Khoảng cách và góc trong không gian cổ điển","description":"Giải bài toán khoảng cách không gian cổ điển trong 90 giây mà không bị rối hình. Bài tập thực hành sau buổi học: Làm phiếu 20 bài toán khoảng cách và góc đa diện khối chóp, lăng trụ.","keyTopics":["Phương pháp chân đường cao và kẻ phụ kẻ vuông góc","Khoảng cách từ điểm đến mặt phẳng, khoảng cách giữa 2 đường chéo nhau","Góc giữa đường thẳng và mặt phẳng, góc giữa hai mặt phẳng"],"durationMinutes":90},{"sessionIndex":8,"title":"Phương pháp tọa độ hóa (gắn hệ trục Oxyz) giải hình không gian","description":"Có vũ khí thứ hai cực mạnh để xử lý mọi bài hình không gian phức tạp khi bí dựng hình. Bài tập thực hành sau buổi học: Tọa độ hóa 10 bài toán khoảng cách từng xuất hiện trong đề thi THPT Quốc gia.","keyTopics":["Quy tắc chọn gốc tọa độ O và các trục Ox, Oy, Oz chuẩn","Chuyển đổi bài toán góc và khoảng cách sang công thức tọa độ","Ứng dụng Oxyz cho lăng trụ xiên và hình chóp có đáy bất kỳ"],"durationMinutes":90},{"sessionIndex":9,"title":"Mặt phẳng, đường thẳng và mặt cầu trong không gian Oxyz","description":"Làm chủ các dạng toán cơ bản và trung bình trong chuyên đề Oxyz để không mất điểm oan. Bài tập thực hành sau buổi học: Giải 30 câu trắc nghiệm Oxyz mức nhận biết - thông hiểu trong 30 phút.","keyTopics":["Vị trí tương đối và bài toán tương giao","Hình chiếu vuông góc của điểm lên mặt phẳng, đường thẳng","Phương trình mặt cầu ngoại tiếp tứ diện và tiếp xúc mặt phẳng"],"durationMinutes":90},{"sessionIndex":10,"title":"Cực trị không gian Oxyz & Kỹ thuật tâm tỉ cự, chuyển điểm","description":"Bẻ khóa câu hỏi phân loại Oxyz 9+ trong đề thi tốt nghiệp. Bài tập thực hành sau buổi học: Hoàn thành 15 bài tập VDC cực trị hình học Oxyz.","keyTopics":["Bài toán Min - Max biểu thức độ dài vectơ","Kỹ thuật tâm tỉ cự tìm điểm cố định I","Mặt phẳng thay đổi chứa đường thẳng tiếp xúc mặt cầu"],"durationMinutes":90},{"sessionIndex":11,"title":"Số phức & Các bài toán hình học số phức (Min - Max Modun)","description":"Ăn trọn điểm số phần số phức trong bài thi THPT. Bài tập thực hành sau buổi học: Làm phiếu 25 bài tập cực trị số phức vận dụng cao.","keyTopics":["Đại số số phức: Modun, liên hợp, nghiệm phức phương trình bậc 2","Tập hợp điểm biểu diễn số phức: Đường thẳng, đường tròn, elip","Cực trị số phức bằng phương pháp hình học và bất đẳng thức tam giác"],"durationMinutes":90},{"sessionIndex":12,"title":"Chiến thuật phòng thi, phân bổ thời gian & Thi thử chuẩn cấu trúc 2026","description":"Rèn luyện tâm lý vững vàng, kỹ năng bấm giờ và hoàn thành bài thi đạt điểm 9+. Bài tập thực hành sau buổi học: Chữa chi tiết từng câu sai trong đề thi thử và lập sổ tay lỗi sai cá nhân.","keyTopics":["Chiến thuật 35 câu đầu trong 35 phút (100% chính xác)","Kỹ thuật loại trừ đáp án, bấm máy tính Casio rà nghiệm","Làm bài thi thử 50 câu bấm giờ thật, phân tích lỗi sai và tổng kết"],"durationMinutes":90}]'::jsonb, '["Học sinh lớp 12 đang ở mức điểm 7.0 - 7.5 muốn bứt phá lên 8.8 - 9.6 điểm","Học sinh thi khối A00, A01, B00, D01 đặt nguyện vọng vào ĐH Y Dược, Ngoại Thương, Bách Khoa","Học sinh hay bị sai sót câu dễ và bế tắc trước các câu Vận dụng cao (VDC)"]'::jsonb, '["Đã nắm chắc lý thuyết sách giáo khoa Toán 12 chương trình chuẩn/nâng cao","Có máy tính Casio fx-580VNX hoặc fx-880BTG và tài liệu ôn thi chuyên đề"]'::jsonb, '[{"question":"Gia sư có chữa bài tập đề thi thử của các trường chuyên không?","answer":"Có. Toàn bộ bài tập vận dụng cao được tuyển chọn từ đề thi thử mới nhất năm 2025-2026 của Chuyên Sư Phạm, Chuyên KHTN, Chuyên Lam Sơn."},{"question":"Em hay tính ẩu sai câu dễ thì khóa học có cải thiện được không?","answer":"Gia sư rèn luyện bảng bẫy lỗi sai (Trap-list) riêng và kỹ thuật bấm máy kiểm tra ngược kết quả trong 15 giây."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000008', 'b2000000-0000-0000-0000-000000000003', 'aaaaaaaa-0001-0000-0000-000000000001', 'Chinh Phục Hình Học Không Gian & Oxyz Lớp 12', 'Khóa học bồi dưỡng chuyên đề cốt lõi giúp học viên lấp đầy lỗ hổng kiến thức và rèn phản xạ nhanh.', 'Các chuyên đề phân loại cao và chiến thuật xử lý các tình huống phức tạp trong bài thi/công việc.', 'Thành thạo kỹ năng giải quyết vấn đề, nâng cao rõ rệt tốc độ và độ chính xác.', 10, 90, 3000000.00, 'Both', 'Published', NOW() - INTERVAL '73 days', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Góc trong không gian: Góc giữa đường thẳng và mặt phẳng, góc nhị diện","description":"Xác định chuẩn xác 100% các góc hình học không gian trong 60 giây. Bài tập thực hành sau buổi học: Giải 20 bài toán góc trong khối chóp và lăng trụ.","keyTopics":["Kỹ năng xác định hình chiếu vuông góc","Góc giữa hai đường thẳng chéo nhau","Góc giữa hai mặt phẳng bằng giao tuyến hoặc góc phẳng"],"durationMinutes":90},{"sessionIndex":2,"title":"Khoảng cách trong không gian cổ điển: Kỹ thuật dời điểm về chân đường cao","description":"Không còn lúng túng trước câu hỏi khoảng cách trong đề thi. Bài tập thực hành sau buổi học: Làm 15 bài toán khoảng cách từ các đề thi chuyên chọn lọc.","keyTopics":["Khoảng cách từ điểm bất kỳ đến mặt phẳng","Tỉ số khoảng cách và phương pháp song song / cắt nhau","Khoảng cách giữa hai đường thẳng chéo nhau"],"durationMinutes":90},{"sessionIndex":3,"title":"Thể tích khối đa diện: Khối chóp, lăng trụ & Tỉ số thể tích Simpson","description":"Tính toán nhanh thể tích các khối đa diện phức tạp bằng tỉ số thể tích. Bài tập thực hành sau buổi học: Hoàn thành phiếu bài tập 25 câu thể tích khối đa diện.","keyTopics":["Công thức thể tích V = 1/3 Bh và V = Bh","Định lý tỉ số thể tích Simpson cho khối chóp tam giác và mở rộng khối chóp tứ giác","Bài toán phân chia khối đa diện"],"durationMinutes":90},{"sessionIndex":4,"title":"Mặt nón, mặt trụ & Mặt cầu ngoại tiếp khối chóp","description":"Vẽ nhanh trục đường tròn đáy và mặt phẳng trung trực tìm bán kính mặt cầu R. Bài tập thực hành sau buổi học: Giải 20 bài toán mặt cầu ngoại tiếp hình chóp.","keyTopics":["Các yếu tố bán kính đáy r, đường sinh l, chiều cao h của nón và trụ","Công thức diện tích xung quanh, toàn phần và thể tích","Phương pháp xác định tâm và bán kính mặt cầu ngoại tiếp khối chóp có cạnh bên vuông góc đáy / mặt bên vuông góc đáy"],"durationMinutes":90},{"sessionIndex":5,"title":"Hệ trục tọa độ Oxyz: Tọa độ điểm, vectơ & Tích có hướng","description":"Thành thạo bấm máy Casio tích có hướng vectơ và gắn trục tọa độ chuẩn. Bài tập thực hành sau buổi học: Thực hành gắn trục Oxyz cho 8 dạng khối chóp thường gặp.","keyTopics":["Các phép toán vectơ trong không gian","Công thức tích có hướng và ứng dụng chứng minh đồng phẳng, tính diện tích tam giác","Phương pháp gắn hệ trục Oxyz vào hình không gian cổ điển"],"durationMinutes":90},{"sessionIndex":6,"title":"Phương trình mặt phẳng & Đường thẳng trong Oxyz","description":"Viết phương trình mặt phẳng và đường thẳng chính xác trong 45 giây. Bài tập thực hành sau buổi học: Làm 30 câu trắc nghiệm viết phương trình Oxyz cơ bản.","keyTopics":["Vectơ pháp tuyến, vectơ chỉ phương","Phương trình tổng quát mặt phẳng, phương trình chính tắc và tham số đường thẳng","Chuyển đổi linh hoạt giữa các dạng phương trình"],"durationMinutes":90},{"sessionIndex":7,"title":"Góc, khoảng cách & Vị trí tương đối trong Oxyz","description":"Áp dụng công thức giải quyết dứt điểm các bài toán không gian bằng đại số. Bài tập thực hành sau buổi học: Làm phiếu 20 bài toán tính toán khoảng cách bằng Oxyz.","keyTopics":["Công thức khoảng cách từ điểm đến mặt phẳng, khoảng cách giữa hai đường thẳng","Góc giữa hai đường thẳng, hai mặt phẳng, đường thẳng và mặt phẳng","Vị trí tương đối của hai đường thẳng: Cắt nhau, song song, chéo nhau"],"durationMinutes":90},{"sessionIndex":8,"title":"Mặt cầu trong Oxyz & Bài toán tương giao mặt phẳng - mặt cầu","description":"Xử lý thành thạo các bài toán mặt cầu cắt mặt phẳng. Bài tập thực hành sau buổi học: Giải 15 bài toán tương giao mặt phẳng và mặt cầu.","keyTopics":["Phương trình chính tắc và phương trình tổng quát mặt cầu","Điều kiện để mặt phẳng tiếp xúc mặt cầu hoặc cắt mặt cầu theo giao tuyến đường tròn","Đường tròn giao tuyến và bài toán tìm tâm, bán kính r"],"durationMinutes":90},{"sessionIndex":9,"title":"Kỹ thuật tâm tỉ cự và Cực trị Min-Max trong Oxyz","description":"Làm chủ dạng toán cực trị Oxyz 8.5+ hay xuất hiện ở cuối đề thi. Bài tập thực hành sau buổi học: Hoàn thành 12 bài toán cực trị tâm tỉ cự VDC.","keyTopics":["Tìm điểm cố định I thỏa mãn hệ thức vectơ","Bài toán tìm điểm M trên mặt phẳng sao cho tổng bình phương khoảng cách nhỏ nhất","Hình chiếu và điểm đối xứng"],"durationMinutes":90},{"sessionIndex":10,"title":"Tổng kết chuyên đề & Luyện giải đề thực chiến 100% câu hỏi Hình học","description":"Tự tin đạt điểm tối đa toàn bộ phần Hình học trong kỳ thi THPT. Bài tập thực hành sau buổi học: Chữa đề và hoàn thiện sổ tay công thức Hình học 12 cá nhân.","keyTopics":["Rà soát toàn bộ công thức và bảng tổng hợp mẹo làm nhanh","Giải trọn vẹn 2 đề thi chuyên sâu 25 câu Hình học không gian & Oxyz bấm giờ","Phân tích chiến thuật chọn phương pháp Cổ điển vs Oxyz"],"durationMinutes":90}]'::jsonb, '["Học sinh lớp 12 bị mất gốc hình học không gian lớp 11 hoặc sợ hình học Oxyz","Học sinh muốn học kỹ thuật tọa độ hóa để không phụ thuộc vào tư duy dựng hình cổ điển","Sĩ tử cần kiếm trọn 2.0 - 2.6 điểm phần Hình học trong đề thi tốt nghiệp THPT"]'::jsonb, '["Có kiến thức vectơ cơ bản của lớp 10 và quan hệ vuông góc lớp 11","Thước kẻ, compa, máy tính Casio fx-580VNX"]'::jsonb, '[{"question":"Em không biết vẽ hình phụ thì có học được phương pháp tọa độ hóa không?","answer":"Phương pháp tọa độ hóa Oxyz sinh ra chính là để giải cứu các bạn yếu vẽ hình phụ. Bạn chỉ cần chọn trục tọa độ là máy tính sẽ xử lý tính toán số học."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000009', 'b2000000-0000-0000-0000-000000000003', 'aaaaaaaa-0001-0000-0000-000000000002', 'Toán Tư Duy & Rèn Kỹ Năng Giải Bài Toán Thực Tế', 'Khóa đào tạo chuyên sâu ứng dụng thực tế giúp học viên đạt mục tiêu mong muốn trong thời gian ngắn nhất.', 'Hệ thống bài tập thực hành theo dự án mẫu và đề thi chuẩn quốc tế/quốc gia.', 'Làm chủ 100% kỹ năng, sẵn sàng chinh phục các kỳ thi và phỏng vấn thực tế.', 8, 90, 2500000.00, 'Both', 'Published', NOW() - INTERVAL '74 days', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Toán học tài chính: Lãi suất ngân hàng, gửi tiết kiệm & Trả góp","description":"Hiểu bản chất dòng tiền và tính toán chính xác lãi suất tiết kiệm. Bài tập thực hành sau buổi học: Giải 15 bài toán tài chính thực tế.","keyTopics":["Công thức lãi đơn và lãi kép","Bài toán gửi tiết kiệm ngân hàng có kỳ hạn","Kế hoạch mua hàng trả góp và chi phí tài chính"],"durationMinutes":90},{"sessionIndex":2,"title":"Tối ưu hóa kinh doanh: Lợi nhuận, Doanh thu & Chi phí sản xuất","description":"Vận dụng hàm số bậc hai giải bài toán kinh tế đời sống. Bài tập thực hành sau buổi học: Làm 12 bài toán tối ưu hóa doanh nghiệp.","keyTopics":["Mối quan hệ giữa giá bán, số lượng sản phẩm tiêu thụ và doanh thu","Xây dựng hàm số bậc hai biểu thị lợi nhuận theo giá bán","Tìm giá bán tối ưu để đạt lợi nhuận cực đại bằng đỉnh parabol"],"durationMinutes":90},{"sessionIndex":3,"title":"Hình học đo đạc thực tế: Đo chiều cao tòa nhà và khoảng cách không tới được","description":"Hiểu cách các kỹ sư trắc địa ứng dụng lượng giác vào thực tế. Bài tập thực hành sau buổi học: Giải 15 bài toán đo đạc thực địa.","keyTopics":["Sử dụng giác kế và thước đo góc","Ứng dụng tỉ số lượng giác sin, cos, tan đo chiều cao cây, ngọn hải đăng","Khoảng cách giữa hai điểm bị ngăn cách bởi dòng sông hoặc chướng ngại vật"],"durationMinutes":90},{"sessionIndex":4,"title":"Toán học kiến trúc: Diện tích sơn nhà, ốp lát gạch và lợp mái tôn","description":"Biết cách bóc tách khối lượng vật liệu xây dựng cho một căn phòng thực tế. Bài tập thực hành sau buổi học: Lập dự toán chi phí sơn sửa một căn phòng ngủ theo bản vẽ mẫu.","keyTopics":["Tính diện tích các mặt tường, trừ diện tích cửa sổ, cửa chính","Tính toán số lượng gạch cần lát sàn và tỉ lệ hao hụt","Diện tích mái ngói hình chóp cụt và khối lăng trụ"],"durationMinutes":90},{"sessionIndex":5,"title":"Toán học dinh dưỡng & Nồng độ dung dịch hóa chất thực tế","description":"Tính toán chuẩn nồng độ pha chế trong đời sống hàng ngày. Bài tập thực hành sau buổi học: Giải 15 bài toán pha trộn dung dịch và dinh dưỡng.","keyTopics":["Tỉ lệ phần trăm dinh dưỡng calo, protein, carb trong khẩu phần ăn","Bài toán pha trộn dung dịch: Muối, cồn sát khuẩn 70 độ, nước đường","Thiết lập phương trình cân bằng nồng độ phần trăm"],"durationMinutes":90},{"sessionIndex":6,"title":"Thống kê & Xác suất thực nghiệm trong phân tích dữ liệu đời sống","description":"Đọc hiểu biểu đồ báo cáo và phân tích số liệu khoa học. Bài tập thực hành sau buổi học: Phân tích bảng số liệu khảo sát người tiêu dùng và viết báo cáo ngắn.","keyTopics":["Thu thập dữ liệu, vẽ biểu đồ hình quạt tròn và biểu đồ đoạn thẳng","Số trung bình cộng, trung vị, mốt và ý nghĩa thực tế","Xác suất thực nghiệm trong trò chơi may rủi và dự báo thời tiết"],"durationMinutes":90},{"sessionIndex":7,"title":"Tư duy logic giải đố & Bài toán chiến thuật trò chơi (Game Theory)","description":"Rèn luyện tư duy logic sắc bén, tư duy thuật toán. Bài tập thực hành sau buổi học: Giải 10 câu đố logic kinh điển.","keyTopics":["Nguyên lý Dirichlet (nguyên lý chuồng bồ câu) ứng dụng","Phương pháp suy luận ngược từ kết quả","Chiến thuật giành chiến thắng trong trò chơi bốc sỏi (Nim game)"],"durationMinutes":90},{"sessionIndex":8,"title":"Báo cáo dự án thực tế & Tổng kết phương pháp tư duy mô hình hóa","description":"Có năng lực chuyển đổi các vấn đề thực tiễn phức tạp thành bài toán cụ thể. Bài tập thực hành sau buổi học: Hoàn thành bài tập dự án ứng dụng toán học cá nhân.","keyTopics":["Quy trình mô hình hóa toán học 4 bước: Đời thực -> Toán học -> Giải toán -> Ứng dụng","Thực hành giải trọn vẹn 1 đề thi chuyên đề Toán thực tế 90 phút","Đánh giá năng lực tư duy giải quyết vấn đề của học viên"],"durationMinutes":90}]'::jsonb, '["Học sinh THCS theo chương trình SGK mới (Cánh Diều, Kết Nối Tri Thức, Chân Trời Sáng Tạo)","Học sinh muốn rèn luyện tư duy phản biện, giải quyết các bài toán tài chính, đo đạc thực tế"]'::jsonb, '["Sổ tay ghi chép","Máy tính bỏ túi"]'::jsonb, '[{"question":"Chương trình mới có nhiều bài toán thực tế không?","answer":"Chương trình mới dành tới 25-30% đề thi cho các bài toán ứng dụng thực tế: Tài chính cá nhân, lãi suất ngân hàng, hình học không gian đời sống."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000010', 'b2000000-0000-0000-0000-000000000004', 'aaaaaaaa-0001-0000-0000-000000000002', 'Luyện Thi Vào Lớp 10 Chuyên Toán & Trường Công Lập', 'Chương trình đào tạo chuyên sâu cá nhân hóa 1 kèm 1 theo năng lực thực tế của học viên.', 'Toàn bộ kiến thức lý thuyết nền tảng và bộ bài tập thực hành vận dụng cao bám sát thực tế.', 'Nắm chắc kiến thức bản chất, tự tin làm bài thi đạt kết quả xuất sắc vượt mục tiêu.', 12, 90, 3600000.00, 'Offline', 'Published', NOW() - INTERVAL '75 days', 'https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Rút gọn biểu thức chứa căn & Các câu hỏi phụ biện luận giá trị","description":"Ăn chắc trọn vẹn 2.0 điểm câu số 1 trong đề thi vào 10. Bài tập thực hành sau buổi học: Làm phiếu 15 bài rút gọn biểu thức và câu hỏi phụ đề thi các tỉnh.","keyTopics":["Quy đồng và biến đổi biểu thức chứa căn bậc hai","Tìm x để biểu thức nhận giá trị nguyên","So sánh biểu thức với một số, tìm x để biểu thức lớn hơn / nhỏ hơn 0"],"durationMinutes":90},{"sessionIndex":2,"title":"Hệ phương trình bậc nhất hai ẩn & Hệ phương trình đối xứng / đẳng cấp","description":"Nắm chắc phương pháp giải hệ phương trình và biện luận tham số. Bài tập thực hành sau buổi học: Giải 20 bài hệ phương trình trích từ đề thi vào 10.","keyTopics":["Phương pháp thế và cộng đại số nâng cao","Giải và biện luận hệ phương trình chứa tham số m","Hệ phương trình đối xứng loại 1, loại 2 và hệ đẳng cấp"],"durationMinutes":90},{"sessionIndex":3,"title":"Giải bài toán bằng cách lập phương trình và hệ phương trình","description":"Thiết lập đúng bảng đại lượng và không bao giờ bị trừ điểm trình bày. Bài tập thực hành sau buổi học: Hoàn thành 12 bài toán đố thực tế.","keyTopics":["Dạng toán chuyển động: Ngược chiều, cùng chiều, đường thủy có dòng nước","Dạng toán năng suất: Làm chung làm riêng, hoàn thành kế hoạch","Dạng toán phần trăm, hình học và toán thực tế"],"durationMinutes":90},{"sessionIndex":4,"title":"Phương trình bậc hai & Định lý Vi-ét ứng dụng nâng cao","description":"Làm chủ câu hỏi Vi-ét phân loại 8.5+. Bài tập thực hành sau buổi học: Giải 20 bài toán Vi-ét nâng cao.","keyTopics":["Công thức nghiệm và biệt thức Delta","Hệ thức Vi-ét và các bài toán biểu thức đối xứng x1, x2","Tìm điều kiện tham số m để phương trình có 2 nghiệm thỏa mãn hệ thức"],"durationMinutes":90},{"sessionIndex":5,"title":"Tương giao giữa đường thẳng (d) và Parabol (P)","description":"Xử lý thành thạo mọi bài toán tương giao đồ thị hàm số lớp 9. Bài tập thực hành sau buổi học: Làm 15 bài toán tương giao d và P.","keyTopics":["Tìm tọa độ giao điểm của (d) và (P)","Điều kiện để (d) cắt (P) tại hai điểm phân biệt cùng dấu, trái dấu","Bài toán diện tích tam giác tạo bởi các giao điểm của (d) và (P)"],"durationMinutes":90},{"sessionIndex":6,"title":"Hình học đường tròn: Góc nội tiếp, góc tạo bởi tiếp tuyến và dây cung","description":"Vẽ hình chuẩn xác và giải quyết trơn tru câu hình ý a, b. Bài tập thực hành sau buổi học: Làm 10 bài hình học đường tròn cơ bản và nâng cao.","keyTopics":["Tính chất tiếp tuyến và các đường thẳng vuông góc","Góc ở tâm, góc nội tiếp, góc tạo bởi tiếp tuyến và dây cung","Phương pháp chứng minh hai đoạn thẳng bằng nhau, song song"],"durationMinutes":90},{"sessionIndex":7,"title":"Tứ giác nội tiếp đường tròn: Dấu hiệu nhận biết và Kỹ thuật chứng minh","description":"Nhận diện nhanh tứ giác nội tiếp và trình bày lập luận chặt chẽ. Bài tập thực hành sau buổi học: Giải 15 bài toán chứng minh tứ giác nội tiếp.","keyTopics":["Bốn dấu hiệu nhận biết tứ giác nội tiếp kinh điển","Chứng minh các điểm cùng thuộc một đường tròn","Ứng dụng tứ giác nội tiếp chứng minh các góc bằng nhau"],"durationMinutes":90},{"sessionIndex":8,"title":"Chứng minh ba điểm thẳng hàng, ba đường đồng quy & Tiếp tuyến","description":"Bẻ khóa câu hình học ý c phân loại học sinh giỏi. Bài tập thực hành sau buổi học: Hoàn thành 8 bài toán chứng minh thẳng hàng và tiếp tuyến.","keyTopics":["Phương pháp góc bẹt (180 độ) và định lý Menelaus / Ceva đơn giản","Kỹ thuật chứng minh tiếp tuyến của đường tròn","Tính chất tâm đường tròn nội tiếp, trực tâm tam giác"],"durationMinutes":90},{"sessionIndex":9,"title":"Bài toán cực trị hình học: Tìm vị trí điểm để diện tích, chu vi đạt Min - Max","description":"Tự tin giải quyết câu hình học ý d lấy điểm 9.5 - 10. Bài tập thực hành sau buổi học: Giải 8 bài toán cực trị hình học.","keyTopics":["Đưa biểu thức hình học về đại số một ẩn","Sử dụng bất đẳng thức tam giác và đoạn vuông góc ngắn hơn đoạn xiên","Vị trí điểm đặc biệt trên đường tròn"],"durationMinutes":90},{"sessionIndex":10,"title":"Bất đẳng thức Cauchy (AM-GM) và Kỹ thuật chọn điểm rơi","description":"Nắm vững phương pháp chứng minh bất đẳng thức cho câu cuối bài thi. Bài tập thực hành sau buổi học: Làm phiếu 20 bài bất đẳng thức Cauchy chọn điểm rơi.","keyTopics":["Bất đẳng thức Cauchy cho 2 số, 3 số dương","Kỹ thuật chọn điểm rơi đối xứng và điểm rơi không đối xứng","Kỹ thuật thêm bớt hạng tử và đổi biến số"],"durationMinutes":90},{"sessionIndex":11,"title":"Bất đẳng thức Schwarz (Cauchy-Schwarz dạng cộng mẫu số)","description":"Có vũ khí cực mạnh để xử lý câu 0.5 - 1.0 điểm cuối cùng trong đề thi. Bài tập thực hành sau buổi học: Giải 15 bài toán bất đẳng thức Schwarz.","keyTopics":["Công thức cộng mẫu số Engel","Kỹ thuật tách mẫu số và đánh giá đại số","Tìm giá trị nhỏ nhất của biểu thức phân thức nhiều biến số"],"durationMinutes":90},{"sessionIndex":12,"title":"Luyện đề thực chiến bấm giờ & Chuẩn hóa kỹ năng trình bày thi vào 10","description":"Sẵn sàng tâm lý, nắm chắc điểm 9+ trong kỳ thi chuyển cấp. Bài tập thực hành sau buổi học: Chữa lại toàn bộ bài thi thử và ghi nhớ barem chấm điểm.","keyTopics":["Giải trọn vẹn 1 đề thi thử vào 10 chuẩn format Sở GD&ĐT trong 120 phút","Chấm chữa chi tiết theo barem điểm chính thức (từng 0.25 điểm)","Tổng kết các lỗi trừ điểm ngớ ngẩn (quên điều kiện, không kết luận)"],"durationMinutes":90}]'::jsonb, '["Học sinh lớp 9 ôn thi vào lớp 10 các trường THPT công lập top 1 hoặc lớp chuyên Toán","Học sinh muốn đạt từ 8.5 đến 9.5 điểm môn Toán thi vào 10"]'::jsonb, '["Kiến thức Đại số và Hình học lớp 9 THCS","Compa, thước kẻ, máy tính fx-580"]'::jsonb, '[{"question":"Gia sư có luyện câu Bất đẳng thức và Hình học ý c, d không?","answer":"Có. Khóa học dành nhiều thời lượng rèn luyện câu phân loại điểm 9-10: Bất đẳng thức Cauchy/Schwarz và các bổ đề hình học tứ giác nội tiếp."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000011', 'b2000000-0000-0000-0000-000000000004', 'aaaaaaaa-0001-0000-0000-000000000002', 'Bứt Phá Điểm Số Toán THCS (Lớp 7-8-9)', 'Khóa học bồi dưỡng chuyên đề cốt lõi giúp học viên lấp đầy lỗ hổng kiến thức và rèn phản xạ nhanh.', 'Các chuyên đề phân loại cao và chiến thuật xử lý các tình huống phức tạp trong bài thi/công việc.', 'Thành thạo kỹ năng giải quyết vấn đề, nâng cao rõ rệt tốc độ và độ chính xác.', 10, 90, 3000000.00, 'Offline', 'Published', NOW() - INTERVAL '76 days', 'https://images.unsplash.com/photo-1509062522246-3755977927d7?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Làm chủ biểu thức đại số, đơn thức, đa thức và các phép toán","description":"Tính toán chính xác không bị nhầm dấu âm dương. Bài tập thực hành sau buổi học: Làm 25 bài tập rút gọn và tính giá trị biểu thức.","keyTopics":["Cộng trừ đơn thức đồng dạng","Nhân chia đơn thức với đa thức","Thu gọn và tính giá trị biểu thức đại số"],"durationMinutes":90},{"sessionIndex":2,"title":"7 hằng đẳng thức đáng nhớ & Kỹ năng biến đổi linh hoạt","description":"Thuộc lòng bản chất 7 hằng đẳng thức và vận dụng mượt mà. Bài tập thực hành sau buổi học: Hoàn thành 30 câu bài tập hằng đẳng thức.","keyTopics":["Bình phương một tổng, một hiệu và hiệu hai bình phương","Lập phương một tổng, một hiệu và tổng/hiệu hai lập phương","Kỹ thuật áp dụng hằng đẳng thức vào bài toán tìm x và tính nhanh"],"durationMinutes":90},{"sessionIndex":3,"title":"Phân tích đa thức thành nhân tử: 4 phương pháp cốt lõi","description":"Phân tích thành nhân tử thành thạo mọi đa thức bậc 2, bậc 3. Bài tập thực hành sau buổi học: Giải 30 bài tập phân tích đa thức thành nhân tử.","keyTopics":["Phương pháp đặt nhân tử chung","Phương pháp dùng hằng đẳng thức","Phương pháp nhóm hạng tử và tách hạng tử"],"durationMinutes":90},{"sessionIndex":4,"title":"Phân thức đại số: Rút gọn, cộng trừ nhân chia phân thức","description":"Rút gọn phân thức đại số chính xác không sai sót. Bài tập thực hành sau buổi học: Làm 20 bài tập rút gọn phân thức.","keyTopics":["Điều kiện xác định của phân thức","Quy đồng mẫu thức nhiều phân thức","Thực hiện phép tính cộng, trừ, nhân, chia phân thức đại số"],"durationMinutes":90},{"sessionIndex":5,"title":"Phương trình bậc nhất một ẩn & Phương trình đưa về dạng tích","description":"Giải chuẩn xác phương trình bậc nhất và phương trình tích. Bài tập thực hành sau buổi học: Giải 25 phương trình các loại.","keyTopics":["Quy tắc chuyển vế và nhân chia","Phương trình chứa ẩn ở mẫu và bước kiểm tra điều kiện","Phương trình tích A(x).B(x) = 0"],"durationMinutes":90},{"sessionIndex":6,"title":"Hình học: Tam giác bằng nhau & Các trường hợp c-c-c, c-g-c, g-c-g","description":"Viết lập luận chứng minh hình học logic, chặt chẽ. Bài tập thực hành sau buổi học: Làm 10 bài tập chứng minh tam giác bằng nhau.","keyTopics":["Chứng minh hai tam giác bằng nhau","Suy ra các cạnh bằng nhau, góc bằng nhau tương ứng","Tam giác cân, tam giác đều và tính chất đường trung trực"],"durationMinutes":90},{"sessionIndex":7,"title":"Định lý Pitago & Tam giác vuông","description":"Tính toán nhanh độ dài các cạnh trong tam giác vuông. Bài tập thực hành sau buổi học: Giải 15 bài toán ứng dụng định lý Pitago.","keyTopics":["Định lý Pitago thuận và đảo","Hệ thức lượng trong tam giác vuông cơ bản","Ứng dụng tính độ dài cạnh trong thực tế"],"durationMinutes":90},{"sessionIndex":8,"title":"Tứ giác đặc biệt: Hình thang, hình bình hành, hình chữ nhật, hình thoi, hình vuông","description":"Nhớ trọn vẹn sơ đồ cây dấu hiệu nhận biết các tứ giác đặc biệt. Bài tập thực hành sau buổi học: Hoàn thành 12 bài toán chứng minh tứ giác đặc biệt.","keyTopics":["Định nghĩa, tính chất và dấu hiệu nhận biết của từng hình","Phương pháp chứng minh một tứ giác là hình thoi / hình vuông","Đường trung bình của tam giác và hình thang"],"durationMinutes":90},{"sessionIndex":9,"title":"Định lý Talet & Tam giác đồng dạng","description":"Làm chủ các bài toán tam giác đồng dạng lớp 8-9. Bài tập thực hành sau buổi học: Giải 15 bài toán tam giác đồng dạng.","keyTopics":["Định lý Talet thuận, đảo và hệ quả","Ba trường hợp đồng dạng của tam giác","Tính tỉ số diện tích của hai tam giác đồng dạng"],"durationMinutes":90},{"sessionIndex":10,"title":"Tổng ôn tập, chữa bài kiểm tra định kỳ & Phương pháp tự học hiệu quả","description":"Tự tin bứt phá điểm 8+ trong các bài thi giữa kỳ và cuối kỳ. Bài tập thực hành sau buổi học: Sửa lại các câu sai trong bài kiểm tra tổng hợp.","keyTopics":["Rà soát lại toàn bộ lỗ hổng kiến thức qua bài test tổng hợp 60 phút","Hướng dẫn cách trình bày bài thi sạch đẹp, khoa học để đạt điểm tối đa","Xây dựng thời gian biểu tự học môn Toán tại nhà"],"durationMinutes":90}]'::jsonb, '["Học sinh THCS đang bị hổng kiến thức căn bản hoặc điểm số dao động 5.0 - 6.5","Học sinh cần củng cố nền tảng Đại số và Hình học để tự tin đạt 8.0 - 9.0 trên lớp"]'::jsonb, '["Sách giáo khoa Toán THCS","Vở ghi chép và dụng cụ vẽ hình"]'::jsonb, '[{"question":"Gia sư có hỗ trợ giải đáp bài tập trên lớp không?","answer":"Có. Gia sư dành 15-20 phút đầu mỗi buổi để giải đáp các bài tập khó trên trường và củng cố ngay kiến thức học sinh chưa hiểu."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
    ('b7000000-0000-0000-0000-000000000012', 'b2000000-0000-0000-0000-000000000004', 'aaaaaaaa-0001-0000-0000-000000000001', 'Bứt Phá Điểm 9+ Môn Toán Thi Tốt Nghiệp THPT', 'Khóa đào tạo chuyên sâu ứng dụng thực tế giúp học viên đạt mục tiêu mong muốn trong thời gian ngắn nhất.', 'Hệ thống bài tập thực hành theo dự án mẫu và đề thi chuẩn quốc tế/quốc gia.', 'Làm chủ 100% kỹ năng, sẵn sàng chinh phục các kỳ thi và phỏng vấn thực tế.', 8, 90, 2500000.00, 'Offline', 'Published', NOW() - INTERVAL '77 days', 'https://images.unsplash.com/photo-1596495578065-6e0763fa1178?w=1200&auto=format&fit=crop&q=80', '[{"sessionIndex":1,"title":"Hàm số & Cực trị hàm đa thức bậc 3, bậc 4","description":"Xử lý thành thạo các câu hỏi trắc nghiệm mức 7.0 - 8.5 về đơn điệu và cực trị trong 90 giây/câu. Bài tập thực hành sau buổi học: Giải 30 bài tập trắc nghiệm hàm số trích từ đề thi thử Chuyên Khoa học Tự nhiên.","keyTopics":["Tính đơn điệu và điều kiện tham số m","Cực trị hàm bậc ba và đường thẳng qua hai cực trị","Kỹ thuật đạo hàm hàm hợp và hàm ẩn"],"durationMinutes":90},{"sessionIndex":2,"title":"Tiệm cận đồ thị hàm số & Đồ thị đạo hàm","description":"Nắm vững phương pháp suy đồ thị và giải quyết nhanh các bài toán cực trị hàm hợp mức 8.5+. Bài tập thực hành sau buổi học: Hoàn thành 25 bài tập sơ đồ V ghép trục cực trị hàm hợp.","keyTopics":["Tiệm cận đứng, tiệm cận ngang của hàm phân thức chứa căn","Phân tích đồ thị hàm f''(x) để tìm cực trị của hàm g(x) = f(u(x))","Kỹ thuật đếm số điểm cực trị bằng sơ đồ V"],"durationMinutes":90},{"sessionIndex":3,"title":"Tương giao đồ thị & Biện luận số nghiệm phương trình chứa tham số","description":"Tự tin giải quyết câu tương giao hàm số trong vòng 2 phút với độ chính xác tuyệt đối. Bài tập thực hành sau buổi học: Làm đề kiểm tra chuyên đề hàm số 30 câu trong 45 phút.","keyTopics":["Kỹ thuật cô lập tham số m","Phương pháp ghép trục giải quyết tương giao hàm hợp","Điểm uốn và tâm đối xứng của đồ thị"],"durationMinutes":90},{"sessionIndex":4,"title":"Mũ & Logarit: Phương trình, bất phương trình và bài toán Min-Max","description":"Nhận diện ngay dạng hàm đặc trưng và xử lý bất phương trình logarit phức tạp. Bài tập thực hành sau buổi học: Giải 20 câu hỏi VDC mũ - logarit trích từ đề chính thức các năm gần đây.","keyTopics":["Đặt ẩn phụ và phương pháp hàm đặc trưng","Bất phương trình logarit chứa tham số","Bài toán cực trị mũ - logarit vận dụng cao (VDC 9+)"],"durationMinutes":90},{"sessionIndex":5,"title":"Nguyên hàm & Tích phân: Kỹ thuật đổi biến và tích phân từng phần","description":"Nắm chắc 100% các câu hỏi tích phân cơ bản và nâng cao. Bài tập thực hành sau buổi học: Thực hành 35 câu bài tập tích phân hàm ẩn mức 8+.","keyTopics":["Công thức nguyên hàm nâng cao và vi phân nhanh","Đổi biến số lượng giác và hàm hữu tỉ","Tích phân từng phần dạng đặc biệt (hàm ẩn, f(x) kết hợp f''(x))"],"durationMinutes":90},{"sessionIndex":6,"title":"Ứng dụng hình học của tích phân: Diện tích hình phẳng & Thể tích tròn xoay","description":"Xử lý mượt mà bài toán ứng dụng tích phân thực tế hay xuất hiện trong cấu trúc mới. Bài tập thực hành sau buổi học: Giải 15 bài toán ứng dụng tích phân trong bài toán kinh tế và kiến trúc xây dựng.","keyTopics":["Công thức tính diện tích hình phẳng giới hạn bởi nhiều đồ thị","Thể tích vật thể tròn xoay quanh trục Ox, Oy","Bài toán thực tế tối ưu hóa chi phí sản xuất bằng tích phân"],"durationMinutes":90},{"sessionIndex":7,"title":"Hình học không gian: Khoảng cách và góc trong không gian cổ điển","description":"Giải bài toán khoảng cách không gian cổ điển trong 90 giây mà không bị rối hình. Bài tập thực hành sau buổi học: Làm phiếu 20 bài toán khoảng cách và góc đa diện khối chóp, lăng trụ.","keyTopics":["Phương pháp chân đường cao và kẻ phụ kẻ vuông góc","Khoảng cách từ điểm đến mặt phẳng, khoảng cách giữa 2 đường chéo nhau","Góc giữa đường thẳng và mặt phẳng, góc giữa hai mặt phẳng"],"durationMinutes":90},{"sessionIndex":8,"title":"Phương pháp tọa độ hóa (gắn hệ trục Oxyz) giải hình không gian","description":"Có vũ khí thứ hai cực mạnh để xử lý mọi bài hình không gian phức tạp khi bí dựng hình. Bài tập thực hành sau buổi học: Tọa độ hóa 10 bài toán khoảng cách từng xuất hiện trong đề thi THPT Quốc gia.","keyTopics":["Quy tắc chọn gốc tọa độ O và các trục Ox, Oy, Oz chuẩn","Chuyển đổi bài toán góc và khoảng cách sang công thức tọa độ","Ứng dụng Oxyz cho lăng trụ xiên và hình chóp có đáy bất kỳ"],"durationMinutes":90}]'::jsonb, '["Học sinh lớp 12 đang ở mức điểm 7.0 - 7.5 muốn bứt phá lên 8.8 - 9.6 điểm","Học sinh thi khối A00, A01, B00, D01 đặt nguyện vọng vào ĐH Y Dược, Ngoại Thương, Bách Khoa","Học sinh hay bị sai sót câu dễ và bế tắc trước các câu Vận dụng cao (VDC)"]'::jsonb, '["Đã nắm chắc lý thuyết sách giáo khoa Toán 12 chương trình chuẩn/nâng cao","Có máy tính Casio fx-580VNX hoặc fx-880BTG và tài liệu ôn thi chuyên đề"]'::jsonb, '[{"question":"Gia sư có chữa bài tập đề thi thử của các trường chuyên không?","answer":"Có. Toàn bộ bài tập vận dụng cao được tuyển chọn từ đề thi thử mới nhất năm 2025-2026 của Chuyên Sư Phạm, Chuyên KHTN, Chuyên Lam Sơn."},{"question":"Em hay tính ẩu sai câu dễ thì khóa học có cải thiện được không?","answer":"Gia sư rèn luyện bảng bẫy lỗi sai (Trap-list) riêng và kỹ thuật bấm máy kiểm tra ngược kết quả trong 15 giây."},{"question":"Học phí có được bảo chứng an toàn (Escrow) không?","answer":"Có. Toàn bộ tiền học phí được giữ an toàn trong hệ thống ký quỹ Escrow của TutorHub. Gia sư chỉ được giải ngân sau khi buổi học hoàn thành và học viên xác nhận hài lòng."},{"question":"Nếu tôi bận việc đột xuất thì có được đổi lịch học không?","answer":"Có. Bạn có thể gửi yêu cầu dời lịch trên hệ thống trước buổi học tối thiểu 12 tiếng để gia sư sắp xếp khung giờ mới thuận tiện cho cả hai."},{"question":"Tôi có thể nhắn tin trao đổi với gia sư trước khi đặt lịch không?","answer":"Hoàn toàn được. Bạn có thể bấm nút \"Nhắn tin với gia sư\" trên trang cá nhân để trao đổi về lộ trình, giáo trình và kiểm tra độ phù hợp trước khi thanh toán."}]'::jsonb),
